const dbList = async (table, { filters = {}, orderBy = null, ascending = false, limit = 100 } = {}) => {
    try {
        const q = new URLSearchParams({ filters: JSON.stringify(filters || {}), limit: String(limit || 100) });
        if (orderBy) { q.set('orderBy', orderBy); q.set('ascending', String(!!ascending)); }
        const r = await storageFetch(`/api/storage/data/${encodeURIComponent(table)}?${q}`);
        return r.data || [];
    } catch (_) { return []; }
};
const dbInsert = async (table, row) => { try { return (await storageFetch(`/api/storage/data/${encodeURIComponent(table)}`, { method:'POST', body:JSON.stringify(row) })).data || null; } catch (_) { return null; } };
const dbUpdate = async (table, id, patch) => { try { return (await storageFetch(`/api/storage/data/${encodeURIComponent(table)}/${encodeURIComponent(id)}`, { method:'PUT', body:JSON.stringify(patch) })).data || null; } catch (_) { return null; } };
const dbDelete = async (table, id) => { try { await storageFetch(`/api/storage/data/${encodeURIComponent(table)}/${encodeURIComponent(id)}`, { method:'DELETE' }); return true; } catch (_) { return false; } };
const dbInsertMany = async (table, rows) => { try { return (await storageFetch(`/api/storage/data/${encodeURIComponent(table)}/bulk`, { method:'POST', body:JSON.stringify(rows) })).data || []; } catch (_) { return []; } };
const dbDeleteWhere = async (table, filters) => {
    try { const rows=await dbList(table,{filters,limit:5000}); for(const row of rows) if(row?.id!==undefined) await dbDelete(table,row.id); return true; } catch (_) { return false; }
};
