// ============================================================================
// GATE PASS DATA ACCESS — see /mnt/user-data/outputs/gate-passes-table-migration.sql
// ============================================================================
// Gate passes used to live as ONE giant JSON array inside a single tnp_kv row, so every
// scan at the gate and every approval click had to download and re-upload the ENTIRE
// historical list just to touch one pass — the actual reason gate scanning didn't feel
// sub-second. They now live in a real `gate_passes` table: one row per pass, with (id,
// status, student_email, qr_token, qr_used) as real indexed columns and the full
// approval-pipeline object (teacher/mentor/guardian/HOD state, notifications, AI-call
// fields, signatures, photos) preserved byte-for-byte inside a `data` jsonb column — so
// none of that business logic needed to change shape, only how it's fetched/saved.
//
// rowToPass/passToRow convert between the DB row shape and the flat pass object the rest
// of the app already works with everywhere (pass.status, pass.qrToken, etc still just work).
const rowToPass = (row) => row ? Object.assign({}, row.data, {
    id: row.id, status: row.status, studentEmail: row.student_email,
    qrToken: row.qr_token, qrUsed: row.qr_used,
}) : null;
const passToRow = (pass) => ({
    id: pass.id, status: pass.status, student_email: pass.studentEmail,
    qr_token: pass.qrToken, qr_used: !!pass.qrUsed, data: pass,
});
// Drop-in for the old "give me every gate pass" fetch — used by views that genuinely need
// full history (admin dashboard, a student's own "my gate passes" tab, analytics). The hot
// scan-verification path uses gatePassFetchOne below instead, which is the actual fix.
const gatePassFetchAll = async () => { try { return (await storageFetch('/api/gate-passes')).data || []; } catch (_) { return []; } };
const gatePassFetchOne = async (id) => { try { return (await storageFetch(`/api/gate-passes/${encodeURIComponent(id)}`)).data || null; } catch (_) { return null; } };
const GATE_PASS_PUBLIC_BASE_URL = '';
const gatePassBaseUrl = () => {
    let storedPublic='', backendPublic='';
    try { storedPublic=String(localStorage.getItem('GATE_PASS_PUBLIC_BASE_URL')||'').trim(); backendPublic=String(localStorage.getItem('AI_BACKEND_URL')||'').trim(); } catch (_) {}
    const configured=String(GATE_PASS_PUBLIC_BASE_URL||window.TNP_PUBLIC_BASE_URL||storedPublic||backendPublic||'').trim();
    const raw=configured||`${location.origin}${location.pathname}`;
    try { const u=new URL(raw,location.href);u.search='';u.hash='';if(/\/api\/?$/i.test(u.pathname))u.pathname=u.pathname.replace(/\/api\/?$/i,'/');return u.toString().replace(/\/$/,''); } catch(_){return String(raw).replace(/[?#].*$/,'').replace(/\/$/,'');}
};
const gatePassOriginIsLocal = () => {
    let configured=''; try { configured=String(GATE_PASS_PUBLIC_BASE_URL||window.TNP_PUBLIC_BASE_URL||localStorage.getItem('GATE_PASS_PUBLIC_BASE_URL')||localStorage.getItem('AI_BACKEND_URL')||'').trim(); } catch(_){}
    if(configured){try{const u=new URL(configured,location.href);return u.protocol==='file:'||/^(localhost|127\.|0\.0\.0\.0|\[::1\])$/i.test(u.hostname);}catch(_){}}
    return location.protocol==='file:'||/^(localhost|127\.|0\.0\.0\.0|\[::1\])$/i.test(location.hostname);
};
const gatePassMergeServerUsage = async (passes) => {
    if(!passes?.length)return passes;
    try{const data=(await storageFetch(`/api/gate-passes/public/usage?ids=${encodeURIComponent(passes.map(p=>p.id).join(','))}`)).data||[];const byId=new Map(data.map(r=>[String(r.id),r]));return passes.map(p=>{const r=byId.get(String(p.id));return r?.qr_used?Object.assign({},p,{qrUsed:true,qrUsedAt:r.qrUsedAt||p.qrUsedAt}):p;});}catch(_){return passes;}
};
