const _gatePassInFlight = new Map();
const _gatePassRedeemOnce = async (id,token) => {
    if(!id||!token)return{status:'invalid'};
    const controller=new AbortController();
    const timer=setTimeout(()=>controller.abort(),30000);
    try{
        const headers={'Content-Type':'application/json'};
        const access=portalAccessToken(); if(access) headers.Authorization=`Bearer ${access}`;
        const res=await fetch(`${portalApiBase()}/api/gate-passes/public/redeem`,{
            method:'POST',credentials:'include',headers,body:JSON.stringify({id,token}),signal:controller.signal
        });
        const r=await res.json().catch(()=>null);
        if(!res.ok) return {status:r?.status||'error',pass:r?.pass||null,message:r?.message||`Verification failed (${res.status})`};
        return{status:r?.status||'error',pass:r?.pass||null,message:r?.message};
    }catch(e){
        return{status:e?.name==='AbortError'?'verification_timeout':'offline',message:e?.name==='AbortError'?'Verification did not complete within 30 seconds. Do NOT admit the student; scan again.':(e?.message||'Could not reach the server.')};
    }finally{clearTimeout(timer);}
};
const gatePassRedeem = async (id,token) => { const key=`${id}:${token}`;if(_gatePassInFlight.has(key))return _gatePassInFlight.get(key);const p=_gatePassRedeemOnce(id,token).then(r=>{setTimeout(()=>_gatePassInFlight.delete(key),r.status==='ok'?1500:0);return r;});_gatePassInFlight.set(key,p);return p; };
