const generateCompanyPYQs = (companyName, count = 100) => {
    const list = [];
    let hash = 0;
    for (let i = 0; i < companyName.length; i++)
        hash = companyName.charCodeAt(i) + ((hash << 5) - hash);
    for (let k = 0; k < count; k++) {
        const seed = Math.abs(hash + k * 1009);
        const tmpl = PYQ_TEMPLATES[seed % PYQ_TEMPLATES.length];
        list.push(Object.assign({ id: `${companyName}-${k}`, company: companyName }, tmpl(seed)));
    }
    return list;
};
