// LEETCODE_BANK — a large (~2500-problem) supplementary bank converted from an uploaded
// LeetCode-style question export, loaded from the inert <script type="application/json"
// id="leetcode-bank-data"> tag above (see index.html head) instead of being inlined as a
// giant JS array literal, so this ~5MB payload parses as JSON (fast, no JS-literal escaping
// concerns) rather than being executed as code. Sits ALONGSIDE the hand-curated
// CODING_BANK_CURATED above and the infinite procedurally-generated bank below — nothing
// from either of those was removed, and titles that already existed in CODING_BANK_CURATED
// were skipped during conversion to avoid duplicates. Unlike the curated/generated bank,
// each entry here already carries its own real difficulty (Easy/Medium/Hard) instead of one
// derived from array position.
let LEETCODE_BANK = [];
const LEETCODE_BANK_READY = (() => {
    const load = async () => {
        try {
            const base = new URL('.', window.location.href);
            const r = await fetch(new URL('leetcode-bank.json', base), { cache: 'force-cache', credentials: 'same-origin' });
            if (!r.ok) throw new Error(`HTTP ${r.status}`);
            const parsed = await r.json();
            LEETCODE_BANK = Array.isArray(parsed) ? parsed : [];
            CODING_BANK.splice(0, CODING_BANK.length, ...CODING_BANK_CURATED, ...LEETCODE_BANK);
            window.dispatchEvent(new CustomEvent('tnp:leetcode-bank-ready'));
            return LEETCODE_BANK;
        } catch (e) {
            console.warn('LeetCode bank lazy-load failed; curated/generated coding bank remains available.', e);
            return [];
        }
    };
    return load();
})();
// CODING_BANK — the combined curated bank used everywhere below (generateCodingQuestion,
// the browsable problem list, etc.). Curated entries keep their original array position
// (and therefore their existing position-derived difficulty formula); LEETCODE_BANK entries
// are appended after them and carry an explicit `difficulty` field that generateCodingQuestion
// prefers over the formula when present.
let CODING_BANK = [...CODING_BANK_CURATED];
const generateCodingQuestion = (index) => {
    const id = index + 1;
    if (index < CODING_BANK.length) {
        const b = CODING_BANK[index];
        const difficulty = b.difficulty || ((index % 5 === 4) ? 'Hard' : (index % 3 === 0 ? 'Easy' : 'Medium'));
        const starters = {};
        ['javascript', 'typescript', 'python', 'java', 'c', 'cpp', 'csharp', 'go', 'rust', 'kotlin', 'swift', 'ruby', 'php'].forEach(l => { starters[l] = CODING_IO_NOTE(l); });
        return { id, title: `#${id}. ${b.title}`, category: b.category, difficulty, description: b.description, link: b.link || '', tests: b.tests, starters, source: 'curated' };
    }
    const rng = mulberry32(id * 2654435761);
    const OPS = [
        { name: 'Sum of Array Elements', category: 'Arrays', desc: 'a line of space-separated integers', run: (arr) => arr.reduce((a, b) => a + b, 0) },
        { name: 'Product of Array Elements', category: 'Arrays', desc: 'a line of space-separated integers (max 8 numbers, values ≤ 20)', run: (arr) => arr.reduce((a, b) => a * b, 1) },
        { name: 'Maximum Element', category: 'Arrays', desc: 'a line of space-separated integers', run: (arr) => Math.max(...arr) },
        { name: 'Minimum Element', category: 'Arrays', desc: 'a line of space-separated integers', run: (arr) => Math.min(...arr) },
        { name: 'Count of Even Numbers', category: 'Arrays', desc: 'a line of space-separated integers', run: (arr) => arr.filter(x => x % 2 === 0).length },
        { name: 'Count of Odd Numbers', category: 'Arrays', desc: 'a line of space-separated integers', run: (arr) => arr.filter(x => x % 2 !== 0).length },
        { name: 'Average (floor)', category: 'Math', desc: 'a line of space-separated integers', run: (arr) => Math.floor(arr.reduce((a, b) => a + b, 0) / arr.length) },
        { name: 'Reverse the Array', category: 'Arrays', desc: 'a line of space-separated integers', run: (arr) => arr.slice().reverse().join(' ') },
        { name: 'Range (Max - Min)', category: 'Arrays', desc: 'a line of space-separated integers', run: (arr) => Math.max(...arr) - Math.min(...arr) },
        { name: 'Sum of Squares', category: 'Math', desc: 'a line of space-separated integers', run: (arr) => arr.reduce((a, b) => a + b * b, 0) },
        { name: 'Count of Positive Numbers', category: 'Arrays', desc: 'a line of space-separated integers', run: (arr) => arr.filter(x => x > 0).length },
        { name: 'Count of Negative Numbers', category: 'Arrays', desc: 'a line of space-separated integers', run: (arr) => arr.filter(x => x < 0).length },
        { name: 'Second Maximum Element', category: 'Arrays', desc: 'a line of space-separated integers (at least 2, values need not be distinct)', run: (arr) => arr.slice().sort((a, b) => b - a)[1] },
        { name: 'Sum of Absolute Values', category: 'Math', desc: 'a line of space-separated integers', run: (arr) => arr.reduce((a, b) => a + Math.abs(b), 0) },
        { name: 'Bitwise XOR of All Elements', category: 'Bit Manipulation', desc: 'a line of space-separated non-negative integers', run: (arr) => arr.reduce((a, b) => a ^ b, 0) },
        { name: 'Cumulative Sum (Prefix Sums)', category: 'Arrays', desc: 'a line of space-separated integers', run: (arr) => { let s = 0; return arr.map(x => (s += x)).join(' '); } },
        { name: 'Sort Descending', category: 'Sorting', desc: 'a line of space-separated integers', run: (arr) => arr.slice().sort((a, b) => b - a).join(' ') },
        { name: 'Count Distinct Elements', category: 'Hashing', desc: 'a line of space-separated integers', run: (arr) => new Set(arr).size },
        { name: 'Maximum Absolute Difference', category: 'Arrays', desc: 'a line of space-separated integers (at least 2)', run: (arr) => Math.max(...arr) - Math.min(...arr) },
        { name: 'Median (lower of two middles if even count)', category: 'Math', desc: 'a line of space-separated integers', run: (arr) => { const s = arr.slice().sort((a, b) => a - b); return s[Math.floor((s.length - 1) / 2)]; } }
    ];
    const op = OPS[id % OPS.length];
    const n = rngInt(rng, 4, 8);
    const arr = Array.from({ length: n }, () => rngInt(rng, -25, 50));
    const expected = String(op.run(arr));
    const arr2 = Array.from({ length: n + 1 }, () => rngInt(rng, -25, 50));
    const arr3 = Array.from({ length: Math.max(3, n - 1) }, () => rngInt(rng, -25, 50));
    const difficulty = (id % 5 === 0) ? 'Hard' : (id % 2 === 0 ? 'Medium' : 'Easy');
    const starters = {};
    ['javascript', 'typescript', 'python', 'java', 'c', 'cpp', 'csharp', 'go', 'rust', 'kotlin', 'swift', 'ruby', 'php'].forEach(l => { starters[l] = CODING_IO_NOTE(l); });
    return {
        id,
        title: `#${id}. ${op.name} — Challenge Set ${((id / OPS.length) | 0) + 1}`,
        category: op.category || 'Generated Numeric Challenge',
        difficulty,
        description: `Read ${op.desc}. Print the result: ${op.name.toLowerCase()}.`,
        tests: [
            { stdin: arr.join(' '), expected },
            { stdin: arr2.join(' '), expected: String(op.run(arr2)) },
            { stdin: arr3.join(' '), expected: String(op.run(arr3)) }
        ],
        starters,
        source: 'generated'
    };
};
