const APTI_CATEGORIES = [
    'synonym', 'antonym', 'analogy', 'one-word', 'idiom', 'sentence-correction', 'para-jumble',
    'number-series', 'coding-decoding', 'direction-sense', 'blood-relation', 'syllogism',
    'age-problem', 'clock-angle', 'calendar', 'critical-reasoning'
];
const generateProceduralAptitudeQuestion = (index) => {
    const id = index + 1;
    const rng = mulberry32(id * 40503 + 7);
    const cat = APTI_CATEGORIES[index % APTI_CATEGORIES.length];
    let group = 'Verbal Ability', question = '', options = [], answerIndex = 0, explanation = '';
    if (cat === 'synonym' || cat === 'antonym') {
        const w = rngPick(rng, HARD_WORDS);
        const correct = cat === 'synonym' ? w.syn : w.ant;
        const distractorPool = HARD_WORDS.filter(x => x.w !== w.w).map(x => cat === 'synonym' ? x.syn : x.ant);
        const distractors = rngShuffle(rng, distractorPool).slice(0, 3);
        const shuffled = shuffleWithAnswer(rng, [correct, ...distractors], 0);
        question = `Select the word closest in meaning to${cat === 'antonym' ? ' the OPPOSITE of' : ''} "${w.w}":`;
        options = shuffled.options;
        answerIndex = shuffled.answerIndex;
        explanation = `"${w.w}" most closely means "${w.syn}" (opposite: "${w.ant}"). The correct ${cat} is "${correct}".`;
    }
    else if (cat === 'analogy') {
        const pair = rngPick(rng, ANALOGY_BANK);
        const distractorPairs = rngShuffle(rng, ANALOGY_BANK.filter(p => p !== pair)).slice(0, 3).map(p => `${p[2]} : ${p[3]}`);
        const correctOpt = `${pair[2]} : ${pair[3]}`;
        const shuffled = shuffleWithAnswer(rng, [correctOpt, ...distractorPairs], 0);
        question = `${pair[0]} is to ${pair[1]} as ${pair[2]} is to ______. Complete the analogy:`;
        options = shuffled.options;
        answerIndex = shuffled.answerIndex;
        explanation = `The relationship "${pair[0]} : ${pair[1]}" mirrors "${pair[2]} : ${pair[3]}".`;
    }
    else if (cat === 'one-word') {
        const item = rngPick(rng, OWS_BANK);
        const distractors = rngShuffle(rng, OWS_BANK.filter(x => x !== item)).slice(0, 3).map(x => x.answer);
        const shuffled = shuffleWithAnswer(rng, [item.answer, ...distractors], 0);
        question = `Choose the single word that means: "${item.phrase}"`;
        options = shuffled.options;
        answerIndex = shuffled.answerIndex;
        explanation = `"${item.phrase}" is best expressed in one word as "${item.answer}".`;
    }
    else if (cat === 'idiom') {
        const item = rngPick(rng, IDIOM_BANK);
        const distractors = rngShuffle(rng, IDIOM_BANK.filter(x => x !== item)).slice(0, 3).map(x => x.meaning);
        const shuffled = shuffleWithAnswer(rng, [item.meaning, ...distractors], 0);
        question = `What does the idiom "${item.idiom}" mean?`;
        options = shuffled.options;
        answerIndex = shuffled.answerIndex;
        explanation = `"${item.idiom}" means: ${item.meaning}.`;
    }
    else if (cat === 'sentence-correction') {
        const item = rngPick(rng, SENTENCE_BANK);
        const shuffled = shuffleWithAnswer(rng, [item.right, item.wrong, item.wrong.replace(/\.$/, ' today.'), item.wrong.replace(/\.$/, ', clearly.')], 0);
        question = `Identify the grammatically CORRECT sentence:`;
        options = shuffled.options;
        answerIndex = shuffled.answerIndex;
        explanation = `The original had an error: "${item.wrong}". Correct form: "${item.right}" — ${item.note}`;
    }
    else if (cat === 'para-jumble') {
        const set = rngPick(rng, PARA_BANK);
        const labeled = set.map((s, i) => String.fromCharCode(65 + i) + '. ' + s);
        const order = [0, 1, 2, 3];
        const correctSeq = order.map(i => String.fromCharCode(65 + i)).join('-');
        const wrongPerms = new Set();
        while (wrongPerms.size < 3) {
            const p = rngShuffle(rng, order);
            const seq = p.map(i => String.fromCharCode(65 + i)).join('-');
            if (seq !== correctSeq)
                wrongPerms.add(seq);
        }
        const jumbledDisplay = rngShuffle(rng, labeled).join('   ');
        const shuffled = shuffleWithAnswer(rng, [correctSeq, ...Array.from(wrongPerms)], 0);
        question = `Rearrange the following sentences (shown out of order) into the most logical sequence:\n${jumbledDisplay}`;
        options = shuffled.options;
        answerIndex = shuffled.answerIndex;
        explanation = `Read in original narrative order, the correct sequence is ${correctSeq} — "${set.join(' ')}"`;
    }
    else if (cat === 'number-series') {
        group = 'Logical Reasoning';
        const patterns = ['arith', 'geo', 'square', 'alt', 'quad'];
        const p = rngPick(rng, patterns);
        let seq = [], next;
        if (p === 'arith') {
            const start = rngInt(rng, 2, 30), d = rngInt(rng, 2, 9);
            seq = Array.from({ length: 5 }, (_, i) => start + i * d);
            next = start + 5 * d;
        }
        else if (p === 'geo') {
            const start = rngInt(rng, 2, 5), r = rngInt(rng, 2, 3);
            seq = Array.from({ length: 5 }, (_, i) => start * Math.pow(r, i));
            next = start * Math.pow(r, 5);
        }
        else if (p === 'square') {
            const start = rngInt(rng, 2, 6);
            seq = Array.from({ length: 5 }, (_, i) => (start + i) * (start + i));
            next = (start + 5) * (start + 5);
        }
        else if (p === 'alt') {
            const a = rngInt(rng, 2, 10), b = rngInt(rng, 3, 12);
            seq = [a, a + b, a + b, a + 2 * b, a + 2 * b].map((v, i) => v + i * 0);
            seq = [a, a + b, a + 2 * b, a + 3 * b, a + 4 * b];
            next = a + 5 * b;
        }
        else {
            const c = rngInt(rng, 1, 4);
            seq = Array.from({ length: 5 }, (_, i) => (i + 1) * (i + 1) + c);
            next = 36 + c;
        }
        const distractors = new Set();
        while (distractors.size < 3) {
            const delta = rngInt(rng, -6, 6);
            if (delta !== 0)
                distractors.add(next + delta);
        }
        const shuffled = shuffleWithAnswer(rng, [String(next), ...Array.from(distractors).map(String)], 0);
        question = `Find the next number in the series: ${seq.join(', ')}, ?`;
        options = shuffled.options;
        answerIndex = shuffled.answerIndex;
        explanation = `The series follows a ${p === 'arith' ? 'constant-difference' : p === 'geo' ? 'constant-ratio' : p === 'square' ? 'perfect-square' : p === 'alt' ? 'constant-step' : 'square-plus-constant'} pattern, so the next term is ${next}.`;
    }
    else if (cat === 'coding-decoding') {
        group = 'Logical Reasoning';
        const word = rngPick(rng, CIPHER_WORDS);
        const shift = rngInt(rng, 1, 12);
        const coded = shiftLetters(word, shift);
        const targetWord = rngPick(rng, CIPHER_WORDS.filter(w => w !== word));
        const correctCoded = shiftLetters(targetWord, shift);
        const distractors = new Set();
        while (distractors.size < 3) {
            const fakeShift = rngInt(rng, 1, 12);
            if (fakeShift !== shift)
                distractors.add(shiftLetters(targetWord, fakeShift));
        }
        const shuffled = shuffleWithAnswer(rng, [correctCoded, ...Array.from(distractors)], 0);
        question = `In a certain code language, "${word}" is written as "${coded}". How would "${targetWord}" be written in the same code?`;
        options = shuffled.options;
        answerIndex = shuffled.answerIndex;
        explanation = `Each letter is shifted forward by ${shift} in the alphabet, so "${targetWord}" becomes "${correctCoded}".`;
    }
    else if (cat === 'direction-sense') {
        group = 'Logical Reasoning';
        const dirs = [[0, 1, 'North'], [1, 0, 'East'], [0, -1, 'South'], [-1, 0, 'West']];
        let dIdx = 0, x = 0, y = 0;
        const steps = rngInt(rng, 3, 5);
        const moves = [];
        for (let i = 0; i < steps; i++) {
            const turn = rngPick(rng, ['left', 'right', 'straight']);
            if (turn === 'left')
                dIdx = (dIdx + 3) % 4;
            else if (turn === 'right')
                dIdx = (dIdx + 1) % 4;
            const dist = rngInt(rng, 2, 15);
            x += dirs[dIdx][0] * dist;
            y += dirs[dIdx][1] * dist;
            moves.push(`walks ${dist} km ${i === 0 ? dirs[dIdx][2] : (turn === 'straight' ? 'straight' : 'after turning ' + turn + ', heading ' + dirs[dIdx][2])}`);
        }
        const straightDist = Math.round(Math.sqrt(x * x + y * y) * 100) / 100;
        const distractors = new Set();
        while (distractors.size < 3) {
            const delta = (rngInt(rng, -5, 5));
            const v = Math.max(1, Math.round((straightDist + delta) * 100) / 100);
            if (v !== straightDist)
                distractors.add(v);
        }
        const shuffled = shuffleWithAnswer(rng, [`${straightDist} km`, ...Array.from(distractors).map(v => `${v} km`)], 0);
        question = `A person starts at point O and ${moves.join(', then ')}. What is the straight-line distance from the starting point?`;
        options = shuffled.options;
        answerIndex = shuffled.answerIndex;
        explanation = `Tracking the net displacement gives coordinates (${Math.round(x * 100) / 100}, ${Math.round(y * 100) / 100}) relative to the start, so by the distance formula the straight-line distance is √(x²+y²) ≈ ${straightDist} km.`;
    }
    else if (cat === 'blood-relation') {
        group = 'Logical Reasoning';
        const t = rngPick(rng, BLOOD_TEMPLATES)(rng);
        question = t.q;
        options = t.options;
        answerIndex = t.answer;
        explanation = t.explanation;
    }
    else if (cat === 'syllogism') {
        group = 'Logical Reasoning';
        const item = rngPick(rng, SYLLOGISM_BANK);
        question = `Statements:\n1) ${item.s1}\n2) ${item.s2}\nWhich conclusion logically follows?`;
        const shuffled = shuffleWithAnswer(rng, item.options, item.answer);
        options = shuffled.options;
        answerIndex = shuffled.answerIndex;
        explanation = item.explanation;
    }
    else if (cat === 'age-problem') {
        group = 'Logical Reasoning';
        const sonAge = rngInt(rng, 8, 20);
        const ageMultiple = rngInt(rng, 3, 5);
        const fatherAge = sonAge * ageMultiple + rngInt(rng, 0, 4);
        const years = rngInt(rng, 5, 15);
        const futureFather = fatherAge + years, futureSon = sonAge + years;
        const distractors = new Set();
        while (distractors.size < 3) {
            const d = rngInt(rng, -6, 6);
            if (d !== 0)
                distractors.add(futureFather + d);
        }
        const shuffled = shuffleWithAnswer(rng, [String(futureFather), ...Array.from(distractors).map(String)], 0);
        question = `A father is currently ${fatherAge} years old and his son is ${sonAge} years old. What will the father's age be in ${years} years?`;
        options = shuffled.options;
        answerIndex = shuffled.answerIndex;
        explanation = `Father's future age = current age + ${years} = ${fatherAge} + ${years} = ${futureFather} years. (For reference, the son will then be ${futureSon}.)`;
    }
    else if (cat === 'clock-angle') {
        group = 'Logical Reasoning';
        const h = rngInt(rng, 1, 12), m = rngPick(rng, [0, 10, 15, 20, 25, 30, 35, 40, 45, 50]);
        const minuteAngle = m * 6;
        const hourAngle = (h % 12) * 30 + m * 0.5;
        let diff = Math.abs(hourAngle - minuteAngle);
        if (diff > 180)
            diff = 360 - diff;
        diff = Math.round(diff * 100) / 100;
        const distractors = new Set();
        while (distractors.size < 3) {
            const d = rngInt(rng, -20, 20);
            const v = Math.max(0, Math.round((diff + d) * 100) / 100);
            if (v !== diff)
                distractors.add(v);
        }
        const shuffled = shuffleWithAnswer(rng, [`${diff}°`, ...Array.from(distractors).map(v => `${v}°`)], 0);
        question = `What is the angle between the hour and minute hands of a clock at ${h}:${String(m).padStart(2, '0')}?`;
        options = shuffled.options;
        answerIndex = shuffled.answerIndex;
        explanation = `Minute hand angle = ${m}×6 = ${minuteAngle}°. Hour hand angle = (${h}×30) + (${m}×0.5) = ${hourAngle}°. Absolute difference (≤180°) = ${diff}°.`;
    }
    else if (cat === 'calendar') {
        group = 'Logical Reasoning';
        const days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
        const startIdx = rngInt(rng, 0, 6);
        const addDays = rngInt(rng, 15, 90);
        const resultIdx = (startIdx + addDays) % 7;
        const distractorIdx = new Set();
        while (distractorIdx.size < 3) {
            const off = rngInt(rng, 1, 6);
            distractorIdx.add((resultIdx + off) % 7);
        }
        const shuffled = shuffleWithAnswer(rng, [days[resultIdx], ...Array.from(distractorIdx).map(i => days[i])], 0);
        question = `If today is ${days[startIdx]}, what day of the week will it be after ${addDays} days?`;
        options = shuffled.options;
        answerIndex = shuffled.answerIndex;
        explanation = `${addDays} mod 7 = ${addDays % 7} day(s) forward from ${days[startIdx]} lands on ${days[resultIdx]}.`;
    }
    else { // critical-reasoning
        const item = rngPick(rng, CRITICAL_BANK);
        const shuffled = shuffleWithAnswer(rng, item.options, item.answer);
        question = item.q;
        options = shuffled.options;
        answerIndex = shuffled.answerIndex;
        explanation = item.explanation;
    }
    return { id, group, topic: cat, difficulty: 'Hard', question, options, answerIndex, explanation };
};
