function lsGetJSON(key, fallback) {
    try {
        const raw = window.localStorage.getItem(key);
        return raw ? JSON.parse(raw) : fallback;
    } catch (_a) { return fallback; }
}
function lsSetJSON(key, value) {
    try { window.localStorage.setItem(key, JSON.stringify(value)); } catch (_a) { /* storage unavailable — feature still works in-session */ }
}
// Small dependency-free trend bar chart used by several panels below.
function MiniTrendChart({ values, labels, color = '#4f46e5', max = 10 }) {
    if (!values || !values.length) return null;
    return React.createElement("div", { className: "flex items-end gap-1.5 h-20" }, values.map((v, i) => (
        React.createElement("div", { key: i, className: "flex-1 flex flex-col items-center gap-1 min-w-0" },
            React.createElement("div", { className: "w-full rounded-t-md transition-all", style: { height: `${Math.max(6, (v / max) * 100)}%`, backgroundColor: color, opacity: 0.55 + (0.45 * (i / Math.max(1, values.length - 1))) }, title: `${labels ? labels[i] : i + 1}: ${v}` }),
            React.createElement("span", { className: "text-[8px] font-bold text-slate-400 truncate w-full text-center" }, labels ? labels[i] : i + 1)
        )
    )));
}
