    const [plan, setPlan] = useState(null);
    const [loadingPlan, setLoadingPlan] = useState(false);
    const [planError, setPlanError] = useState('');
    const lastLoggedRef = useRef(null);
    useEffect(() => {
        if (!lastFeedback) return;
        const sig = `${lastFeedback.score}::${lastFeedback.verdict}::${currentTrack ? currentTrack.id : ''}`;
        if (lastLoggedRef.current === sig) return; // don't double-log the same feedback object
        lastLoggedRef.current = sig;
        const entry = { date: new Date().toISOString().slice(0, 10), score: Number(lastFeedback.score) || 0, track: currentTrack ? currentTrack.company : 'General', improvements: lastFeedback.improvements || '' };
        setHistory(prev => {
            const next = [...prev, entry].slice(-25);
            lsSetJSON('interviewHistory_v1', next);
            return next;
        });
    }, [lastFeedback]);
    const avgScore = history.length ? (history.reduce((s, h) => s + h.score, 0) / history.length).toFixed(1) : '—';
    const weakTags = useMemo(() => {
        const stop = new Set(['the', 'and', 'for', 'with', 'that', 'this', 'your', 'you', 'more', 'need', 'could', 'should', 'also', 'into', 'from', 'when', 'while', 'about', 'their']);
        const freq = {};
        history.forEach(h => (h.improvements || '').toLowerCase().replace(/[^a-z\s]/g, ' ').split(/\s+/).forEach(w => {
            if (w.length > 4 && !stop.has(w)) freq[w] = (freq[w] || 0) + 1;
        }));
        return Object.entries(freq).sort((a, b) => b[1] - a[1]).slice(0, 6);
    }, [history]);
