        if (!hasAiKey) { onNeedApiKey(); return; }
        setLoadingPlan(true); setPlanError(''); setPlan(null);
        try {
            const summary = history.slice(-8).map(h => `${h.date} [${h.track}] score ${h.score}/10 — gaps: ${h.improvements}`).join('\n') || 'No prior attempts logged yet.';
            const sys = 'You are a campus placement interview coach. Given a student\'s recent mock-interview history, output ONLY strict JSON: {"summary": string, "days": [{"day": number, "focus": string, "tasks": [string, string, string]}]} with exactly 7 entries in days, tasks concise and actionable.';
            const text = await callAiProvider(sys, `Recent mock interview history:\n${summary}\n\nBuild a focused 7-day improvement plan.`, { jsonMode: true, maxTokens: 900 });
            let cleaned = text.trim().replace(/^```[a-zA-Z]*\s*/, '').replace(/```\s*$/, '');
            const parsed = JSON.parse(cleaned);
            setPlan(parsed);
        } catch (err) {
            setPlanError(err.message || 'Could not generate a plan right now.');
            showToast && showToast(err.message || 'AI plan generation failed', 'error');
        } finally { setLoadingPlan(false); }
