// 5) APTITUDE / QUIZ TAB — Adaptive Difficulty Practice Engine.
// ---------------------------------------------------------------------------------
function AdaptivePracticePanel({ callAiProvider, parseAiJson, hasAiKey, showToast, onNeedApiKey }) {
    const [topic, setTopic] = useState('Quantitative Aptitude');
    const [difficulty, setDifficulty] = useState(3); // 1-5
    const [streak, setStreak] = useState(0);
    const [question, setQuestion] = useState(null);
    const [selected, setSelected] = useState(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const DIFF_LABELS = ['Very Easy', 'Easy', 'Medium', 'Hard', 'Very Hard'];
    const fetchQuestion = async () => {
        if (!hasAiKey) { onNeedApiKey(); return; }
        setLoading(true); setError(''); setSelected(null); setQuestion(null);
        try {
            const sys = 'You are an adaptive aptitude test engine for campus placements. Output ONLY strict JSON: {"question": string, "options": [string,string,string,string], "correctIndex": number, "explanation": string}. Exactly one correct option.';
            // Pinned to Groq: this panel fires one AI call per question at a fast, steady pace
            // (every "Next Question" click), which burns through Gemini's free-tier request
            // quota (20/day) far quicker than the slower, heavier panels elsewhere in the app.
            // Groq's free tier is much more generous for small JSON completions like this one,
            // and callAiProvider already auto-retries against Gemini if Groq itself ever fails
            // (bad/missing key, outage, rate limit) — so this is strictly more resilient than
            // inheriting whatever provider happens to be globally selected in Settings.
            const text = await callAiProvider(sys, `Topic: ${topic}. Difficulty level: ${DIFF_LABELS[difficulty - 1]} (${difficulty}/5). Generate one fresh multiple-choice question at this difficulty, not seen before.`, { jsonMode: true, maxTokens: 500, provider: 'groq' });
            const parsed = parseAiJson ? parseAiJson(text) : JSON.parse(text.trim().replace(/^```[a-zA-Z]*\s*/, '').replace(/```\s*$/, ''));
            setQuestion(parsed);
        } catch (err) {
            setError(err.message || 'Could not generate a question.');
            showToast && showToast(err.message || 'Question generation failed', 'error');
        } finally { setLoading(false); }
    };
    const answer = (idx) => {
        if (selected !== null || !question) return;
        setSelected(idx);
        const correct = idx === question.correctIndex;
        setStreak(s => {
            const next = correct ? s + 1 : 0;
            if (correct && next % 3 === 0) setDifficulty(d => Math.min(5, d + 1));
            if (!correct) setDifficulty(d => Math.max(1, d - 1));
            return next;
        });
    };
    return React.createElement(AiPanelShell, { icon: 'zap', title: 'Adaptive Difficulty Practice Engine', subtitle: 'Difficulty auto-tunes to your streak — 3 correct in a row levels you up, one miss levels you down.', badge: `Level: ${DIFF_LABELS[difficulty - 1]} · Streak ${streak}` },
        React.createElement("div", { className: "flex flex-wrap gap-2 items-center" },
            React.createElement("select", { value: topic, onChange: e => setTopic(e.target.value), className: "bg-white border border-indigo-200 rounded-xl px-3 py-2 text-xs font-bold" },
                ['Quantitative Aptitude', 'Logical Reasoning', 'Verbal Ability', 'Data Interpretation', 'Coding Fundamentals'].map(t => React.createElement("option", { key: t, value: t }, t))),
            React.createElement(AiKeyNotice, { hasAiKey, onNeedApiKey }),
            React.createElement("button", { onClick: fetchQuestion, disabled: loading, className: "px-4 py-2 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 text-white font-bold text-xs rounded-xl transition flex items-center gap-2" },
                React.createElement(Icon, { name: loading ? 'loader' : 'sparkles', className: `w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}` }),
                loading ? 'Generating…' : (question ? 'Next Question' : 'Start Practice'))),
        error && React.createElement("p", { className: "text-[11px] text-rose-600 font-bold" }, error),
        question && React.createElement("div", { className: "bg-white border border-indigo-200 rounded-2xl p-4 space-y-2.5" },
            React.createElement("p", { className: "text-xs font-bold text-slate-800" }, question.question),
            React.createElement("div", { className: "grid grid-cols-1 sm:grid-cols-2 gap-2" }, (question.options || []).map((opt, i) => {
                const isCorrect = i === question.correctIndex;
                const show = selected !== null;
                const cls = show ? (isCorrect ? 'bg-emerald-50 border-emerald-300 text-emerald-800' : (i === selected ? 'bg-rose-50 border-rose-300 text-rose-800' : 'bg-slate-50 border-slate-200 text-slate-500')) : 'bg-slate-50 border-slate-200 hover:bg-indigo-50 text-slate-700';
                return React.createElement("button", { key: i, onClick: () => answer(i), disabled: show, className: `text-left p-2.5 rounded-xl border text-[11px] font-bold transition ${cls}` }, opt);
            })),
            selected !== null && React.createElement("p", { className: "text-[11px] text-slate-500 bg-slate-50 border border-slate-200 rounded-xl p-2.5" }, React.createElement("b", null, "Explanation: "), question.explanation)));
}

