    useEffect(() => { setSgAiResult(null); setSgAiError(''); }, [sgCurrentSkills, sgTargetRole, sgCustomRole]);
    // ===== ADVANCED — ACTIONABLE WEEKLY ROADMAP (AI/ML Intelligence Service) =====
