    const [sgCareerPathError, setSgCareerPathError] = useState('');
    const handlePredictCareerPath = async () => {
        const base = getAiMlServiceUrl();
        const currentSkillsArr = (sgCurrentSkills || '').split(',').map(s => s.trim()).filter(Boolean);
        setSgCareerPathLoading(true); setSgCareerPathError(''); setSgCareerPath(null);
        try {
            const res = await aimlFetch(`${base}/career-path/predict`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ current_skills: currentSkillsArr, target_interest: sgEffectiveRole, top_n: 3 }),
            });
            if (!res.ok) {
                // Surface the gateway's own explanation (service asleep / token mismatch / older build ...) instead of a bare status code.
                let detail = '';
                try { const j = await res.json(); detail = (j && (j.detail || (j.error && j.error.message))) || ''; } catch (_e) { }
                throw new Error(String(detail || `AI/ML service returned ${res.status}`).slice(0, 220));
            }
            const data = await res.json();
            setSgCareerPath(data);
            if (data.matches && data.matches[0]) {
                window.CP_syncResult && window.CP_syncResult('ROADMAP', data.matches[0].title, data.matches[0].confidence, 'Career Path Match', data);
            }
        } catch (err) {
            // Local career-path fallback keeps the feature usable during an ML service cold start.
            const have = new Set(currentSkillsArr.map(s => String(s).toLowerCase()));
            const matches = Object.entries(SG_ROLE_SKILLS).map(([title, skills]) => {
                const matched = skills.filter(s => have.has(s.toLowerCase()));
                const missing = skills.filter(s => !have.has(s.toLowerCase()));
                const confidence = skills.length ? Math.round((matched.length / skills.length) * 100) : 0;
                return { id: title.toLowerCase().replace(/[^a-z0-9]+/g, '-'), title, confidence, matched_skills: matched, missing_skills: missing, milestones: missing.slice(0, 5).map((s, i) => ({ week: String(i + 1), focus: `Learn ${s} and build one small project feature using it.` })), evidence: { method: 'deterministic skill overlap', matched_count: matched.length, required_count: skills.length } };
            }).sort((a, b) => b.confidence - a.confidence).slice(0, 3);
            setSgCareerPath({ matches, rationale: matches[0] ? `Based on the skills you entered, ${matches[0].title} has the highest overlap in the local career-path dataset.` : 'Add a few skills to generate a career-path match.', llm_enriched: false, ai_unavailable: true });
            setSgCareerPathError(`Live AI/ML enrichment is temporarily unavailable${err && err.message ? ` (${String(err.message).slice(0, 220)})` : ''}. Showing a deterministic career-path match from your current skills.`);
        } finally {
            setSgCareerPathLoading(false);
        }
    };
    // ===== CAREER FIT — Step 2 -> Step 3/4 handoff =====
