    const NEG_CITY_MULT = { 'Bengaluru': 1.15, 'Hyderabad': 1.05, 'Pune': 1.0, 'Chennai': 0.95, 'Delhi NCR': 1.1, 'Mumbai': 1.12, 'Remote': 1.0, 'Tier-2 City': 0.8 };
    const negBenchmark = useMemo(() => {
        const base = { 'Software Engineer': 6, 'Data Analyst': 5.5, 'Data Scientist': 8, 'DevOps Engineer': 7, 'Product Manager': 10, 'QA Engineer': 4.5, 'UI/UX Designer': 5 }[negRole] || 5.5;
        const expMult = 1 + (parseFloat(negExp) || 0) * 0.18;
        const cityMult = NEG_CITY_MULT[negCity] || 1;
        const mid = base * expMult * cityMult;
        return { low: +(mid * 0.85).toFixed(1), mid: +mid.toFixed(1), high: +(mid * 1.25).toFixed(1) };
    }, [negRole, negExp, negCity]);
    const negScript = useMemo(() => {
        const offer = parseFloat(negOffer) || 0;
        if (!offer)
            return null;
        const gap = negBenchmark.mid - offer;
        if (gap > 0.5) {
            return `"Thank you for the offer — I'm genuinely excited about this role. Based on my research of market rates for a ${negRole} with ${negExp} years of experience in ${negCity}, roles are typically benchmarked between ₹${negBenchmark.low}L–₹${negBenchmark.high}L. Given my skill set and the value I can bring, would there be flexibility to move closer to ₹${negBenchmark.mid}L? I'm confident we can find a number that works for both sides."`;
        }
        return `"Thank you — this offer of ₹${offer}L is already competitive against the market benchmark of ₹${negBenchmark.low}L–₹${negBenchmark.high}L for this profile. I'd like to accept, and wanted to ask if there's any flexibility on the joining bonus or ESOPs to round things out."`;
    }, [negOffer, negBenchmark, negRole, negExp, negCity]);
