        if (target && target.userEmail) {
            const replyLine = reply ? ` Admin note: ${reply}` : '';
            sendGenericEmail(target.userEmail, `Your suggestion was marked "${status}"`, `Your "${target.category}" suggestion has been reviewed and marked as "${status}".${replyLine}`).catch(() => { });
        }
