    useEffect(() => { saveStored('TNP_DARK_MODE', darkMode); document.documentElement.classList.toggle('dark-mode', darkMode); }, [darkMode]);
    const [lastSeenFlashId, setLastSeenFlashId] = useState(() => loadStored('TNP_LAST_SEEN_FLASH', 0));
    const [showNotifDropdown, setShowNotifDropdown] = useState(false);
    const [notifPermission, setNotifPermission] = useState(typeof Notification !== 'undefined' ? Notification.permission : 'unsupported');
    const unreadFlashCount = useMemo(() => flashNewsList.filter(f => f.id > lastSeenFlashId).length, [flashNewsList, lastSeenFlashId]);
    // Gate pass badge counts for admin (awaiting HOD) AND teacher/mentor (awaiting their own
