        if (tid) localStorage.setItem('EMAILJS_TEMPLATE_ID', tid); else localStorage.removeItem('EMAILJS_TEMPLATE_ID');
        if (pk) localStorage.setItem('EMAILJS_PUBLIC_KEY', pk); else localStorage.removeItem('EMAILJS_PUBLIC_KEY');
        // Server copy — this is what actually sends password-reset codes.
        setEmailJsBusy(true);
