        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to)) { setEmailJsTestMsg({ ok: false, text: 'Enter the e-mail address to send the test to.' }); return; }
        setEmailJsBusy(true);
        try {
            const r = await storageFetch('/api/portal-auth/admin/email-test', { method: 'POST', body: JSON.stringify({ to }) });
            if (r.ok) setEmailJsTestMsg({ ok: true, text: r.message });
            else setEmailJsTestMsg({ ok: false, text: (r.hint || r.error || 'Sending failed.') + (r.status ? ' (EmailJS HTTP ' + r.status + (r.detail ? ': ' + r.detail : '') + ')' : '') });
        } catch (err) { setEmailJsTestMsg({ ok: false, text: err.message || 'Could not reach the server.' }); }
