        const groundedSystemPrompt = `${systemPrompt}${ragBlock}\n\nUse the supplied live portal data when it is relevant. Do not invent exact recruiter, eligibility, score, or student-stat values. If the data is insufficient, say so.`;
        return await callAiProviderStream(groundedSystemPrompt, userPrompt, Object.assign({}, opts, { noCache: true }), onDelta);
