    // successful in-browser read and (b) as a recovery path when the browser could not extract any text.
    const parseResumeOnServer = async (file) => {
        const form = new FormData();
        form.append('file', file, file.name);
        form.append('use_llm_enrichment', 'true');
        const res = await aimlFetch(`${aimlBaseUrl()}/parse/resume`, { method: 'POST', body: form });
        if (!res.ok) { let m = `AI/ML parser returned ${res.status}`; try { const j = await res.json(); m = j.detail || (j.error && j.error.message) || m; } catch (_) { } throw new Error(typeof m === 'string' ? m : `AI/ML parser returned ${res.status}`); }
        return res.json();
    };
    const textFromParsedSections = (parsed) => {
        const sec = parsed && parsed.sections;
        if (!sec || typeof sec !== 'object') return '';
        return Object.entries(sec).map(([k, v]) => (k === 'header' ? '' : `${String(k).toUpperCase()}\n`) + String(v || '')).join('\n\n').trim();
    };
    const handleResumeFile = async (file) => {
        setResumeFileError('');
        setResumeParsed(null);
        if (!file)
            return;
        if (file.size > MAX_RESUME_FILE_BYTES) {
            setResumeFileError('That file is too large — please upload something under 5MB.');
            return;
        }
        const lower = file.name.toLowerCase();
        const isPdf = lower.endsWith('.pdf') || file.type === 'application/pdf';
        const isDocx = lower.endsWith('.docx') || file.type === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
        const isDoc = lower.endsWith('.doc') && !isDocx;
        const looksTextual = /\.(txt|md|rtf|csv)$/i.test(file.name) || file.type.startsWith('text/');
        if (isDoc) {
            setResumeFileError('Legacy .doc files can\'t be parsed in-browser — please save it as .docx or .pdf, or paste the text below.');
            return;
        }
        if (!looksTextual && !isPdf && !isDocx) {
            setResumeFileError('Unsupported file type. Upload a .pdf, .docx, or .txt resume, or paste your resume text directly below.');
            return;
        }
        setResumeFileLoading(true);
        try {
            let text;
            if (isPdf) text = cleanExtractedResumeText(await extractPdfText(file));
            else if (isDocx) text = cleanExtractedResumeText(await extractDocxText(file));
            else text = await file.text();
            if ((!text || !text.trim()) && (isPdf || isDocx)) {
                try {
                    const parsed = await parseResumeOnServer(file);
                    const recovered = textFromParsedSections(parsed);
                    if (recovered) { setResumeText(recovered); setResumeFileName(file.name); setResumeParsed(parsed); setResumeFileLoading(false); return; }
                } catch (_) { /* fall through to the normal message */ }
            }
            if (!text || !text.trim()) {
                setResumeFileError(isPdf
                    ? 'No selectable text found in that PDF — it may be a scanned image. Paste the resume text below instead.'
                    : 'Couldn\'t find any text in that file. Paste your resume text below instead.');
                setResumeFileLoading(false);
                return;
            }
            setResumeText(text);
            setResumeFileName(file.name);
            if (isPdf || isDocx) parseResumeOnServer(file).then(setResumeParsed).catch(() => { });
        } catch (err) {
            if (isPdf || isDocx) {
                try {
                    const parsed = await parseResumeOnServer(file);
                    const recovered = textFromParsedSections(parsed);
                    if (recovered) { setResumeText(recovered); setResumeFileName(file.name); setResumeParsed(parsed); return; }
                } catch (_) { /* fall through */ }
            }
            setResumeFileError((err && err.message) || 'Could not read that file — try a different format or paste the text below.');
        } finally {
            setResumeFileLoading(false);
        }
    };
