        if (useCustomJD && !customJDText.trim()) {
            showToast('Paste the job description you want to match against.', 'error');
            return;
        }
        const company = companiesList.find(c => c.name === resumeMatchCompany) || companiesList[0];
        let jdText;
        if (useCustomJD) {
            jdText = customJDText;
        }
        else {
            const syllabus = getSyllabusForCompany(company);
            jdText = `${company.role} ${company.name} ${syllabus.topics.join(' ')} ${syllabus.rounds.join(' ')}`;
        }
        setAiResumeAnalysis(null);
        setAiResumeAnalysisError('');
        // Primary path is now the real LLM match (semantic — understands synonyms &
