            // 2) Older browser-gateway LLM path (only if a provider key is configured); otherwise -> local result below.
            if (!hasWorkingAi) throw new Error(aimlFailureNote(viaMl, 'resume analysis'));
            const systemPrompt = `You are an expert campus-placement resume reviewer. Compare the candidate's resume against the target job description/role. Be specific and actionable. Return plain text (no markdown headers, use short paragraphs and "- " bullet points), covering: (1) overall fit summary in 1-2 sentences, (2) top 3-5 concrete gaps vs the JD, (3) 3-5 rewritten/tailored bullet point suggestions the candidate could add to their resume, (4) one formatting or clarity tip. Keep it under 300 words.`;
            const userPrompt = `RESUME:\n${sanitizeInput(resumeText).slice(0, 6000)}\n\nTARGET ROLE / JOB DESCRIPTION:\n${sanitizeInput(jdText).slice(0, 4000)}`;
            const text = await callAiProvider(systemPrompt, userPrompt, { maxTokens: 900 });
