    // Kept short and concrete so the prompt sent to the model stays unambiguous.
    const PPT_IMAGE_STYLES = [
        { id: 'flat', label: 'Flat Illustration', prompt: 'clean flat vector illustration, simple shapes, soft color palette, no text or watermarks' },
        { id: 'photo', label: 'Photorealistic', prompt: 'photorealistic, natural lighting, professional stock-photo style, no text or watermarks' },
        { id: 'iso', label: 'Isometric', prompt: 'isometric 3D illustration, clean minimal style, soft shadows, no text or watermarks' },
        { id: 'sketch', label: 'Line Art / Sketch', prompt: 'minimal line-art sketch, monochrome with a single accent color, no text or watermarks' },
        { id: 'corp', label: 'Corporate Icon', prompt: 'simple corporate icon / infographic style, bold shapes, flat colors, no text or watermarks' }
    ];
    const [pptRawText, setPptRawText] = useState('');
    const [pptDeckTitle, setPptDeckTitle] = useState('');
    const [pptDeckSubtitle, setPptDeckSubtitle] = useState('');
