            cover.addText('AI Powered Campus A-Z Placement and Training Portal — Live Recruiter Database', { x: 0.7, y: 6.9, w: 12, h: 0.4, fontSize: 10, color: theme.titleText, transparency: 30, fontFace: 'Arial' });
