                const slide = pptx.addSlide();
                slide.background = { color: theme.bg };
                slide.addShape('rect', { x: 0, y: 0, w: W, h: 0.9, fill: { color: theme.accent } });
                slide.addText(`Active Campus Placement Drives${Math.ceil(openDrives.length / rowsPerSlide) > 1 ? ` (${p + 1}/${Math.ceil(openDrives.length / rowsPerSlide)})` : ''}`, { x: 0.5, y: 0.12, w: 12.3, h: 0.65, fontSize: 22, bold: true, color: theme.titleText, fontFace: 'Arial' });
