function aimlNormSkill(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ''); }
function aimlSkillVariants(label) {
    const parts = String(label || '').split(/[\/&,]| and /).map(aimlNormSkill).filter(Boolean);
    const whole = aimlNormSkill(label);
    return whole && !parts.includes(whole) ? parts.concat([whole]) : parts;
}
function aimlHasSkill(label, have) {
    const vs = aimlSkillVariants(label);
    for (const h of have) {
        if (!h) continue;
        for (const v of vs) {
            if (h === v) return true;
            if (h.length >= 4 && v.length >= 4 && (h.includes(v) || v.includes(h))) return true;
        }
    }
    return false;
}
function aimlOfflineRoles() { return Object.keys(AIML_MARKET_FALLBACK.roles).sort(); }
function aimlResolveRole(query) {
    const q = String(query || '').trim().toLowerCase().replace(/\s+/g, ' ');
    if (!q) return null;
    const alias = {};
    Object.entries(AIML_MARKET_FALLBACK.roles).forEach(([role, info]) => { alias[role.toLowerCase()] = role; (info.aliases || []).forEach(a => { alias[String(a).toLowerCase()] = role; }); });
    if (alias[q]) return alias[q];
    const has = (needle, hay) => new RegExp('(?<![a-z0-9])' + needle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(?![a-z0-9])').test(hay);
    let bestAlias = '', best = null;
    Object.entries(alias).forEach(([a, role]) => { if (a.length >= 3 && (has(a, q) || has(q, a)) && a.length > bestAlias.length) { bestAlias = a; best = role; } });
    if (best) return best;
    const words = new Set(q.match(/[a-z0-9]+/g) || []);
    let size = 1;
    Object.entries(alias).forEach(([a, role]) => { const w = a.match(/[a-z0-9]+/g) || []; if (w.length > size && w.every(x => words.has(x))) { size = w.length; best = role; } });
    return best;
}
function aimlOfflineRadar(targetRole, currentSkills) {
    const requested = String(targetRole || '').trim().replace(/\s+/g, ' ').slice(0, 180);
    const role = aimlResolveRole(requested);
    const have = new Set((currentSkills || []).map(aimlNormSkill).filter(Boolean));
    let source, name = role || requested || 'General Software Engineer', mode;
    if (role) { source = AIML_MARKET_FALLBACK.roles[role].skills.map(s => ({ skill: s.skill, demand: s.demand, growth: s.growth || 'stable' })); mode = 'offline dataset (built into the portal)'; }
    else { source = [['Core domain fundamentals', 90], ['Problem solving', 85], ['Communication', 75], ['Version control', 70], ['Testing', 68], ['Project delivery', 65]].map(([skill, demand]) => ({ skill, demand, growth: 'baseline' })); mode = 'generic baseline (role not in the offline dataset)'; }
    const rows = source.sort((a, b) => b.demand - a.demand).map(m => ({ skill: m.skill, market_demand: m.demand, growth: m.growth, you_have_it: aimlHasSkill(m.skill, have) }));
    const missing = rows.filter(r => !r.you_have_it).slice(0, 8);
    const haveCount = rows.filter(r => r.you_have_it).length;
    const top = rows.slice(0, 10);
    return {
        target_role: name, matched_from_query: requested, coverage_pct: rows.length ? Math.round(1000 * haveCount / rows.length) / 10 : 0,
        skills: rows, missing_high_demand_skills: missing, top_priority_skill: missing[0] ? missing[0].skill : null, top_priority_skill_evidence: null,
        data_mode: mode, offline: true,
        radar_chart: { categories: top.map(r => r.skill), market_demand: top.map(r => r.market_demand), your_coverage: top.map(r => r.you_have_it ? 100 : 0) },
    };
}
function aimlOfflineTrending() {
    const seen = {};
    Object.entries(AIML_MARKET_FALLBACK.roles).forEach(([role, info]) => info.skills.forEach(s => {
        if (s.growth === 'rising' && (!seen[s.skill] || s.demand > seen[s.skill].demand)) seen[s.skill] = Object.assign({}, s, { example_role: role });
    }));
    return { trending: Object.values(seen).sort((a, b) => b.demand - a.demand).slice(0, 15), data_mode: 'offline dataset (built into the portal)' };
}

