// ---------------------------------------------------------------------------------
// ANALYTICS — interactive hover charts + a simple linear-regression trend predictor,
// computed live from the `gate_passes` and `library_loans` tables (previously based on
// attendance, which has been removed from the portal along with the Attendance tab).
// ---------------------------------------------------------------------------------
function linearRegressionPredict(points, futureXs) {
    const n = points.length;
    if (n < 2) return null;
    const sumX = points.reduce((s, p) => s + p.x, 0);
    const sumY = points.reduce((s, p) => s + p.y, 0);
    const sumXY = points.reduce((s, p) => s + p.x * p.y, 0);
    const sumX2 = points.reduce((s, p) => s + p.x * p.x, 0);
    const denom = (n * sumX2 - sumX * sumX);
    if (denom === 0) return null;
    const slope = (n * sumXY - sumX * sumY) / denom;
    const intercept = (sumY - slope * sumX) / n;
    return futureXs.map(x => Math.max(0, Math.min(100, slope * x + intercept)));
}
