// ---------------------------------------------------------------------------------
// EXAM NOTES & ANSWER-PDF GENERATOR — student answers a short profile (UG/PG + class,
// self-rated prep level, hours available today, preferred answer style), then uploads a
// photo or PDF of the question paper. The AI reads it (vision for images, extracted text
// for PDFs), auto-detects the marks allotted to each question, writes an answer whose
// depth/length is calibrated to those marks + the student's profile, and the whole set
// is exported as a downloadable answer-key PDF via jsPDF.
// ---------------------------------------------------------------------------------
// ---------------------------------------------------------------------------------
// SKILL HUB — AI Concept-to-Video Doubt Clarification
// A student types a doubt ("Explain polymorphism", "I don't understand inheritance"...),
// picks a duration/level, and the AI (via the existing secure callAiProvider -> backend
// /api/ai proxy — same plumbing every other AI Tools tab already uses, so no new backend
// surface or API keys are introduced) plans a timed lesson: narration script + on-screen
// visuals (bullets / code / auto-diagrams / worked examples) broken into duration-matched
// segments. Those segments are then played back as a synced "video" — the built-in browser
// speech engine (SpeechSynthesis) narrates each segment with a human-sounding voice while
// the matching visual is shown, captions run underneath, and the slide auto-advances when
// the narration for it finishes — giving a real watch-and-listen lesson entirely on-device,
// with no paid video/TTS API or API key required. Ends in an AI-tutor follow-up chat that
// stays in context of the lesson just generated.
// ---------------------------------------------------------------------------------

function MiniDiagram({ nodes = [], edges = [] }) {
    if (!nodes.length) return null;
    const w = 640, boxW = 132, boxH = 44, gapX = 26, rowMax = 3;
    const rows = Math.ceil(nodes.length / rowMax);
    const positions = nodes.map((_, i) => {
        const row = Math.floor(i / rowMax);
        const col = i % rowMax;
        const perRow = Math.min(rowMax, nodes.length - row * rowMax);
        const rowW = perRow * boxW + (perRow - 1) * gapX;
        const startX = (w - rowW) / 2;
        return { x: startX + col * (boxW + gapX), y: row * (boxH + 46) + 16 };
    });
    const h = rows * (boxH + 46) + 16;
    return React.createElement("svg", { viewBox: `0 0 ${w} ${h}`, className: "w-full", style: { maxHeight: 260 } },
        React.createElement("defs", null,
            React.createElement("marker", { id: "aivt-arrow", markerWidth: 8, markerHeight: 8, refX: 6, refY: 4, orient: "auto" },
                React.createElement("path", { d: "M0,0 L8,4 L0,8 Z", fill: "#6366f1" }))),
        edges.map((e, i) => {
            const from = positions[e[0]], to = positions[e[1]];
            if (!from || !to) return null;
            const x1 = from.x + boxW / 2, y1 = from.y + boxH, x2 = to.x + boxW / 2, y2 = to.y;
            const sameRow = Math.abs(from.y - to.y) < 1;
            const mx1 = sameRow ? from.x + boxW : x1, my1 = sameRow ? from.y + boxH / 2 : y1;
            const mx2 = sameRow ? to.x : x2, my2 = sameRow ? to.y + boxH / 2 : y2;
            return React.createElement("line", { key: i, x1: mx1, y1: my1, x2: mx2, y2: my2, stroke: "#818cf8", strokeWidth: 2, markerEnd: "url(#aivt-arrow)" });
        }),
        nodes.map((n, i) => {
            const p = positions[i];
            return React.createElement("g", { key: i },
                React.createElement("rect", { x: p.x, y: p.y, width: boxW, height: boxH, rx: 12, fill: "#eef2ff", stroke: "#6366f1", strokeWidth: 1.5 }),
                React.createElement("foreignObject", { x: p.x + 4, y: p.y + 4, width: boxW - 8, height: boxH - 8 },
                    React.createElement("div", { style: { fontSize: 10, fontWeight: 700, color: "#3730a3", textAlign: "center", display: "flex", alignItems: "center", justifyContent: "center", height: "100%", lineHeight: 1.15, wordBreak: "break-word" } }, n)));
        }));
}

