                    applications: Array.isArray(rawA.applications) ? rawA.applications : [],
                    advantages: Array.isArray(rawA.advantages) ? rawA.advantages : [],
                    limitations: Array.isArray(rawA.limitations) ? rawA.limitations : [],
                    commonMistakes: Array.isArray(rawA.commonMistakes) ? rawA.commonMistakes : [],
                    examinerFollowUps: Array.isArray(rawA.examinerFollowUps) ? rawA.examinerFollowUps : []
