                        id: Date.now(), company: parsed.company || resolvedCompany, role: resolvedRole, type: parsed.category || resolvedCategory,
                        category: parsed.category || resolvedCategory, topic: parsed.topic || 'Custom Interview Problem',
                        prompt: parsed.prompt, scenario: parsed.scenario || '', constraints: Array.isArray(parsed.constraints) ? parsed.constraints.slice(0, 4) : [],
