                const userPrompt = `Company: "${resolvedCompany}"\nRole: "${resolvedRole}"\nGenerate the ${MI_APT_QUESTION_COUNT} questions now.`;
                const raw = await callAiProvider(sys, userPrompt, { maxTokens: 1400, temperature: 0.9, jsonMode: true });
