            loadFaceApiModels()
                .then(() => setMiVisionReady(true))
                .catch(err => {
                    console.warn('MirrorMentor-X vision models unavailable — camera preview still works, eye-contact/posture/identity scoring will be skipped:', err);
                    setMiVisionReady(false);
                    setMiVisionNote("Vision scoring is unavailable right now (couldn't load the face-tracking model), but your camera preview and voice analysis still work.");
                });
