const PR_TESTT = ['unit test', 'unit-test', 'integration test', 'e2e', 'end-to-end', 'selenium', 'jest', 'pytest', 'postman', 'test case', 'test plan', 'load test', 'uat', 'user testing', 'validation', 'cross-validation', 'k-fold', 'precision', 'recall', 'f1', 'accuracy', 'coverage', 'regression test', 'stress test', 'benchmark', 'mocha', 'cypress', 'junit', 'confusion matrix', 'smoke test', 'black-box', 'white-box', 'beta test', 'pilot', 'fallback'];
const PR_COMPARE = ['baseline', 'compared', ' vs ', 'versus', 'improv', 'reduced', 'increase', 'faster', 'better than', 'outperform', 'saves', 'saved', 'less than', 'under '];
const PR_DEPLOY = ['deployed', 'hosted', 'live', 'production', 'vercel', 'render', 'heroku', 'aws', 'azure', 'gcp', 'netlify', 'firebase', 'docker', 'static site', 'demo'];
const PR_SEC = ['auth', 'jwt', 'oauth', 'bcrypt', 'hash', 'encrypt', 'https', 'tls', 'rbac', 'role-based', 'role based', 'validation', 'sanitiz', 'csrf', 'xss', 'injection', 'rate limit', 'privacy', 'consent', 'gdpr', 'dpdp', 'bias', 'fairness', 'ethic', 'responsible', 'scalab', 'load balanc', 'cache', 'horizontal', 'docker', 'kubernetes', 'cdn', 'queue', 'password', 'token', 'session', 'cors', 'audit', 'anonymi', 'on-device', 'api key'];
const PR_FIRST = ['i built', 'i designed', 'i developed', 'i implemented', 'my role', 'responsible for', 'i was', 'i led', 'i owned', 'i contributed', 'i wrote', 'i created', 'i integrated', 'i deployed', 'my contribution'];
const PR_NUMRE = /\d+(\.\d+)?\s?(%|ms|s\b|sec|x\b|users|students|records|rows|accuracy|f1|k\b|mb|gb|recruiters|companies)/g;

// Fully-offline desk review (also the safety net when the AI is unavailable).
function prLocalDeskReview(p, strictKey) {
    const purpose = prPurposeOf(p.reviewPurpose);
    const off = (PR_STRICT[strictKey] || PR_STRICT.standard).off;
    const F = (k) => (p[k] || '').trim();
    const W = (k) => misWords(F(k)).length;
    const all = prProfileText(p).toLowerCase();
    const stack = prStackList(p);
    const lines = (s) => s.split(/\n|;|•|-\s/).map((x) => x.trim()).filter((x) => x.length > 6).length;
    const S = {};
    const probText = `${F('problem')} ${F('abstract')}`.toLowerCase();
    S.problem = 1 + (W('problem') >= 25 ? 3 : W('problem') >= 12 ? 2 : W('problem') > 0 ? 1 : 0) + (misHasAny(probText, PR_USERS) ? 2 : 0) + (misHasAny(probText, PR_MOTIVE) ? 2 : 0) + (lines(F('objectives')) >= 2 ? 2 : lines(F('objectives')) === 1 ? 1 : 0) + (misCountMatches(`${F('problem')} ${F('objectives')}`, PR_NUMRE) > 0 ? 0.5 : 0);
    const nov = misCountHits(all, PR_NOV);
    S.novelty = (nov === 0 ? 2 : nov === 1 ? 4 : nov === 2 ? 5.5 : nov === 3 ? 7 : 8) + (W('abstract') >= 50 ? 1 : 0);
    S.design = 0.5 + Math.min(4.2, misCountHits(all, PR_ARCH) * 0.7) + (W('architecture') >= 20 ? 2.5 : W('architecture') >= 8 ? 1.2 : 0) + (misHasAny(all, PR_DIAG) ? 1.3 : 0) + (stack.length >= 3 ? 1.5 : stack.length >= 2 ? 1 : 0);
    S.impl = 0.5 + (stack.length >= 5 ? 3 : stack.length >= 3 ? 2.4 : stack.length >= 2 ? 1.8 : stack.length >= 1 ? 1 : 0) + (W('abstract') >= 60 ? 2 : W('abstract') >= 30 ? 1 : 0) + Math.min(4, misCountHits(all, PR_IMPL) * 0.7) + (F('link') ? 1 : 0) + (W('role') >= 8 ? 0.5 : 0);
    const tr = `${F('testing')} ${F('results')}`.toLowerCase();
    S.testing = (W('testing') === 0 ? 1 : 3 + (W('testing') >= 10 ? 1 : 0)) + Math.min(4.5, misCountHits(tr, PR_TESTT) * 1.1) + (misCountMatches(tr, PR_NUMRE) > 0 ? 1 : 0);
    const resNums = misCountMatches(`${F('results')} ${F('abstract')}`.toLowerCase(), PR_NUMRE);
    S.results = (W('results') === 0 ? 1 : W('results') >= 12 ? 3.5 : 2.5) + Math.min(3, resNums * 1.2) + (misHasAny(F('results').toLowerCase(), PR_COMPARE) ? 1.5 : 0) + ((W('deployment') > 0 || misHasAny(all, PR_DEPLOY)) ? 1 : 0) + (misHasAny(F('results').toLowerCase(), ['pilot', 'feedback', 'survey', 'testers', 'students', 'users']) ? 1 : 0);
    S.security = 1 + Math.min(6.5, misCountHits(all, PR_SEC)) + (W('limitations') >= 6 ? 1.5 : 0) + (misHasAny(all, ['limitation', 'risk', 'future']) ? 0.5 : 0);
    S.ownership = 1 + (W('role') >= 8 ? 3 : W('role') >= 3 ? 1.5 : 0) + (misCountHits(F('role').toLowerCase(), PR_FIRST) >= 2 ? 3 : misCountHits(F('role').toLowerCase(), PR_FIRST) === 1 ? 1.5 : 0) + (/(team of|solo|individual|\b\d+\s?(members|people|students|developers)\b|guided by|mentor|team project)/.test(F('role').toLowerCase()) ? 2 : 0);
    const comp = prCompleteness(p);
    const sentences = F('abstract').split(/[.!?]+/).filter((x) => x.trim().length > 8).length;
    S.comm = 0.5 + (comp.pct / 100) * 5 + (sentences >= 4 ? 1.5 : sentences >= 2 ? 0.8 : 0) + (W('notes') >= 150 ? 1.5 : 0) + (F('link') ? 0.8 : 0) + (F('title') ? 0.5 : 0);
    // An offline keyword heuristic can only ever verify that something is *mentioned*, so it is deliberately capped.
    Object.keys(S).forEach((k) => { S[k] = Math.min(S[k], 8.5); });
    if (misCountMatches(tr, PR_NUMRE) === 0) S.testing = Math.min(S.testing, 6.5);
    const rubric = {};
    PR_RUBRIC.forEach((r) => {
        const sc = misHalf(S[r.key] + off * 0.6);
        rubric[r.key] = { score: sc, comment: PR_COMMENTS[r.key][sc < 4.5 ? 0 : sc < 7 ? 1 : 2] };
    });
    const risks = [];
    if (purpose && purpose.id === 'btech4' && resNums === 0) risks.push({ severity: 'high', text: 'This major-project context expects measurable results; add at least one reproducible metric and explain how it was measured.' });
    if (purpose && purpose.id.startsWith('hackathon') && !F('link') && !misHasAny(all, ['demo', 'deployed', 'hosted'])) risks.push({ severity: 'medium', text: 'Hackathon reviews benefit from a directly inspectable working demo or repository link.' });
    if (purpose && purpose.id === 'hackathon-international' && !misHasAny(all, ['impact', 'global', 'scale', 'scalab'])) risks.push({ severity: 'medium', text: 'International hackathon context: explain broader impact, scale or transferability of the solution.' });
    if (resNums === 0) risks.push({ severity: 'high', text: 'No measurable results are stated — a panel cannot verify any claim without numbers.' });
    if (W('testing') === 0) risks.push({ severity: 'high', text: 'No testing or validation is described.' });
    if (/\b(ai|ml|machine learning|deep learning|nlp|neural|llm|gpt)\b/.test(all) && !misHasAny(all, ['dataset', 'accuracy', 'f1', 'precision', 'recall', 'training', 'epoch', 'loss', 'prompt', 'embedding', 'fine-tun', 'provider'])) risks.push({ severity: 'high', text: 'AI/ML is claimed but the model, data and evaluation are not described — expect “what does the AI actually do?”.' });
    if (misHasAny(all, ['100%', 'perfect', 'zero error', 'revolutionary', 'unhackable', 'best in the world', 'no errors'])) risks.push({ severity: 'medium', text: 'Absolute claims (“100%”, “perfect”) invite challenge — replace them with measured figures.' });
    if (nov < 1) risks.push({ severity: 'medium', text: 'No comparison with existing solutions or papers — novelty is unsupported.' });
    if (W('role') < 3) risks.push({ severity: 'medium', text: 'Personal contribution is not stated — panels always ask “what did YOU build?”.' });
    if (W('architecture') < 8) risks.push({ severity: 'medium', text: 'Architecture and data flow are not described.' });
    if (misHasAny(all, ['login', 'password', 'personal', 'resume', 'email', 'payment', 'user data', 'account']) && misCountHits(all, ['encrypt', 'hash', 'bcrypt', 'jwt', 'https', 'auth', 'privacy', 'consent', 'on-device']) === 0) risks.push({ severity: 'medium', text: 'The project handles user data but no protection measures are mentioned.' });
    if (W('limitations') < 4) risks.push({ severity: 'low', text: 'No honest limitations or future scope — reviewers trust projects that name their weaknesses.' });
    if (!F('link') && !misHasAny(all, ['demo', 'deployed', 'hosted'])) risks.push({ severity: 'low', text: 'No repository, deployment or demo reference.' });
    const order = PR_RUBRIC.slice().sort((a, b) => rubric[b.key].score - rubric[a.key].score);
    const strengths = order.filter((r) => rubric[r.key].score >= 6.5).slice(0, 4).map((r) => `${r.label}: ${rubric[r.key].comment}`);
    const gaps = order.slice().reverse().filter((r) => rubric[r.key].score < 6.5).slice(0, 4).map((r) => `${r.label}: ${rubric[r.key].comment}`);
    const plan = order.slice().reverse().slice(0, 5).map((r) => ({ dimension: r.key, action: PR_ACTIONS[r.key].action, effort: PR_ACTIONS[r.key].effort }));
    const total = prWeightedTotal(Object.keys(rubric).reduce((m, k) => { m[k] = rubric[k].score; return m; }, {}), p.stage);
    const weakest = order[order.length - 1];
    const evidence = prEvidenceProfile(p);
    return {
        source: 'local', rubric, strengths, gaps, risks, plan, total,
        evidenceQuality: evidence.evidenceQuality, evidence,
        likelyQuestions: prLocalQuestions(p, PR_PERSONAS.map((x) => x.id), 6, rubric, false).map((q) => ({ persona: q.persona, dimension: q.dim, question: q.text })),
        oneLiner: `Estimated from the submitted evidence: strongest on ${PR_RUBRIC_BY_KEY[order[0].key].label.toLowerCase()}, weakest on ${PR_RUBRIC_BY_KEY[weakest.key].label.toLowerCase()}.`,
    };
}
