    const covered = [], missed = [];
    secs.forEach(([label, kws]) => (kws.some((k) => a.includes(k)) ? covered : missed).push(label));
    const off = (PR_STRICT[strictKey] || PR_STRICT.standard).off;
    let score = covered.length * 1.6 + (w >= 120 ? 1.5 : w >= 60 ? 1 : w >= 25 ? 0.4 : 0) + Math.min(0.5, misStructureHits(text) * 0.15) + off * 0.6;
