        design: Math.min(1, (misCountHits(all, PR_ARCH) / 8) + (misWords(f('architecture')) / 45) + (misHasAny(all, PR_DIAG) ? .25 : 0)),
        impl: Math.min(1, (stack / 5) + (misCountHits(all, PR_IMPL) / 8) + (misWords(f('role')) / 60)),
        testing: Math.min(1, tests / 5 + metrics / 4),
        results: Math.min(1, metrics / 4 + (compare ? .35 : 0) + (misWords(f('results')) / 70)),
        security: Math.min(1, misCountHits(all, PR_SEC) / 7 + misWords(f('limitations')) / 60),
        ownership: Math.min(1, misCountHits(f('role').toLowerCase(), PR_FIRST) / 2 + misWords(f('role')) / 60),
