    const total = prWeightedTotal(scores, stageId);
    const verdict = prVerdictFor(total);
    const ordered = PR_RUBRIC.slice().sort((a, b) => dims[b.key].score - dims[a.key].score);
    const remarks = personas.map((id) => {
        const per = PR_PERSONA_BY_ID[id];
        const f = per.focus.slice().sort((a, b) => dims[b].score - dims[a].score);
        const best = f[0], worst = f[f.length - 1];
        const line = dims[best].score >= 6.5
            ? `Good on ${PR_RUBRIC_BY_KEY[best].label.toLowerCase()} (${dims[best].score}/10). ${dims[worst].score < 6.5 ? `My concern is ${PR_RUBRIC_BY_KEY[worst].label.toLowerCase()} (${dims[worst].score}/10): ${PR_ACTIONS[worst].action}` : 'No major concerns in my area.'}`
            : `My main concern is ${PR_RUBRIC_BY_KEY[worst].label.toLowerCase()} (${dims[worst].score}/10). ${PR_ACTIONS[worst].action}`;
        return { persona: id, remark: line };
    });
