function prDownloadPdf(r, showToast) {
    const Ctor = window.jspdf && window.jspdf.jsPDF;
    if (!Ctor) { showToast && showToast('PDF engine failed to load — check your connection and try again.', 'error'); return; }
    try {
        const doc = new Ctor({ orientation: 'portrait', unit: 'pt', format: 'a4' });
        const mx = 42, pw = 595 - mx * 2; let y = 50;
        const need = (h) => { if (y + h > 800) { doc.addPage(); y = 50; } };
        const head = (t, size, color) => { doc.setFont('helvetica', 'bold'); doc.setFontSize(size); doc.setTextColor.apply(doc, color || [15, 23, 42]); need(size + 8); doc.text(t, mx, y); y += size + 6; };
        const body = (t, color, indent) => { doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5); doc.setTextColor.apply(doc, color || [51, 65, 85]); doc.splitTextToSize(String(t || ''), pw - (indent || 0)).forEach((ln) => { need(13); doc.text(ln, mx + (indent || 0), y); y += 13; }); };
        const rule = () => { y += 4; need(8); doc.setDrawColor(226, 232, 240); doc.line(mx, y, mx + pw, y); y += 12; };
        head('Project Review Report', 18);
        body(`${r.profileTitle} · ${PR_STAGE_LABEL(r.stage)} · ${r.date} · Strictness: ${r.strict}`, [71, 85, 105]);
        rule();
        head(`${r.verdict.label} — ${r.total} / 100`, 13, [79, 70, 229]);
        body(r.oneLiner || r.verdict.blurb);
        rule(); head('Rubric scores', 11);
        PR_RUBRIC.forEach((x) => { body(`${x.label}: ${r.dims[x.key].score}/10 — ${r.dims[x.key].comment}`); });
        if (r.strengths.length) { rule(); head('Strengths', 10.5, [4, 120, 87]); r.strengths.forEach((s) => body(`• ${s}`)); }
        if (r.gaps.length) { rule(); head('Gaps', 10.5, [180, 83, 9]); r.gaps.forEach((s) => body(`• ${s}`)); }
        if (r.risks.length) { rule(); head('Risk flags', 10.5, [190, 18, 60]); r.risks.forEach((s) => body(`• [${s.severity.toUpperCase()}] ${s.text}`)); }
        if (r.plan.length) { rule(); head('Action plan', 10.5); r.plan.forEach((s, i) => body(`${i + 1}. (${s.effort}) ${s.action}`)); }
        if (r.remarks.length) { rule(); head('Panel remarks', 10.5, [109, 40, 217]); r.remarks.forEach((m) => body(`${PR_PERSONA_BY_ID[m.persona].name}: ${m.remark}`)); }
        if (r.answers.length) {
            rule(); head('Live Q&A', 10.5);
            r.answers.forEach((a, i) => { head(`Q${i + 1} (${PR_PERSONA_BY_ID[a.persona].name} · ${a.score}/10)`, 9.5, [79, 70, 229]); body(a.question); body(`Answer: ${a.answer || '(skipped)'}`, [71, 85, 105], 8); if (a.reaction) body(`Reviewer: ${a.reaction}`, [15, 23, 42], 8); });
        }
        doc.save(`project-review-${(r.profileTitle || 'project').replace(/[^a-z0-9]+/gi, '-').toLowerCase()}-${r.id}.pdf`);
    } catch (_e) { showToast && showToast('Could not build the PDF — please try again.', 'error'); }
}

