    const toggle = (i) => setChecked((c) => { const n = Object.assign({}, c, { [i]: !c[i] }); const all = lsGetJSON(MIS_ACTIONS_KEY, {}); all[report.id] = n; lsSetJSON(MIS_ACTIONS_KEY, all); return n; });
    const prev = history.filter((e) => e.kind === 'project-review' && e.id !== report.id && e.dims).slice(-1)[0];
