// ── Advanced evidence explainability + project bundle ingestion ────────────────────────
const PR_EVIDENCE_UPGRADES = {
    problem: { strong: 'Name the affected users, quantify the pain, document how you verified it, and connect the finding to one design decision.', partial: 'Add a specific user group, current workaround and one measurable pain point or validation source.' },
    novelty: { strong: 'Cite at least two comparable systems/papers, state the difference, and show why the difference matters with evidence.', partial: 'Name comparable solutions and explain one concrete difference instead of using broad “unique/better” claims.' },
    design: { strong: 'Include an architecture diagram or precise data flow, explain key trade-offs, and tie each major choice to a requirement.', partial: 'Describe modules and request/data flow, then explain why the main technologies were chosen.' },
    impl: { strong: 'Show the modules you personally built, important algorithms/API paths, and a reproducible code-level demonstration.', partial: 'Separate your contribution from framework/library functionality and identify the important modules you implemented.' },
    testing: { strong: 'Provide named test cases, counts, pass/fail results, test environment, and repeatable evidence such as logs or automated reports.', partial: 'Add concrete test cases and measurable pass/fail or coverage information; “tested manually” alone is not enough.' },
    results: { strong: 'Show measured outcomes, sample size, baseline/comparison and the exact method used to calculate the metric.', partial: 'Replace qualitative claims with at least one number and state what it was compared against and how it was measured.' },
    security: { strong: 'Document authentication/authorisation, data protection, threat considerations, privacy/ethics controls and scaling safeguards.', partial: 'Name the sensitive data or attack surface and one concrete protection/control, not only “secure”.' },
    ownership: { strong: 'Map your personal contribution to specific modules, commits/design decisions and a defense-ready explanation of how they work.', partial: 'List the exact modules/features you personally built and one implementation detail you can defend.' },
    comm: { strong: 'Keep a reviewer-friendly README with setup, architecture, screenshots/demo, test evidence, limitations and reproducible steps.', partial: 'Add setup/run instructions, screenshots or demo access, and a concise evidence-backed explanation of the system.' },
};
const PR_EVIDENCE_LABELS = { strong: 'Strong evidence', partial: 'Partial evidence', gap: 'Evidence gap' };
function prEvidenceStatus(pct) { return pct >= 75 ? 'strong' : pct >= 45 ? 'partial' : 'gap'; }
function prEvidenceBreakdown(p, key) {
    const f = k => String(p && p[k] || '').trim();
    const all = prProfileText(p).toLowerCase();
    const testsText = `${f('testing')} ${f('results')}`;
    const checks = [];
    const add = (label, ok, detail) => checks.push({ label, ok: !!ok, detail });
    if (key === 'problem') {
        add('Problem is explicit', misWords(f('problem')).length >= 12, `${misWords(f('problem')).length} words in the problem statement`);
        add('Named users/stakeholders', misHasAny(`${f('problem')} ${f('objectives')}`.toLowerCase(), PR_USERS), 'Look for a concrete affected user group');
        add('Pain/current workaround', misHasAny(f('problem').toLowerCase(), ['manual','slow','cost','delay','waste','workaround','today','currently','existing']), 'Explain what happens without the project');
    } else if (key === 'novelty') {
        add('Existing work/alternatives named', misCountHits(all, PR_NOV) >= 2, 'Name comparable tools, systems or papers');
        add('Difference is explicit', misHasAny(all, ['different','unlike','novel','unique','instead','additional','integrat','combine']), 'State exactly what changes');
        add('Reason/evidence for difference', misHasAny(all, ['because','for example','e.g','result','measured','comparison','baseline']), 'Back the distinction with a source or comparison');
    } else if (key === 'design') {
        add('Architecture described', misWords(f('architecture')).length >= 20, `${misWords(f('architecture')).length} words in architecture`);
        add('Data/request flow', misHasAny(all, PR_DIAG), 'Show UI → API → service/database or equivalent flow');
        add('Technology choices', prStackList(p).length >= 3, `${prStackList(p).length} technologies identified`);
    } else if (key === 'impl') {
        add('Concrete tech stack', prStackList(p).length >= 3, `${prStackList(p).length} stack items`);
        add('Implementation detail', misCountHits(all, PR_IMPL) >= 2, 'Mention algorithms, APIs, modules, pipelines or handlers');
        add('Personal contribution', misWords(f('role')).length >= 10 && misHasAny(f('role').toLowerCase(), PR_FIRST), 'Identify what you personally built');
    } else if (key === 'testing') {
        const metricCount = misCountMatches(testsText, PR_NUMRE);
        add('Named test methods', misCountHits(testsText, PR_TESTT) >= 2, 'Unit/integration/manual/user/model validation');
        add('Measured test evidence', metricCount >= 1, `${metricCount} numeric test/result signal(s)`);
        add('Repeatability', misHasAny(testsText.toLowerCase(), ['test case','postman','automated','regression','coverage','log','report','repeat','reproduc']), 'Explain how another reviewer can repeat it');
    } else if (key === 'results') {
        const metricCount = misCountMatches(testsText, PR_NUMRE);
        add('Numeric outcome', metricCount >= 1, `${metricCount} numeric result signal(s)`);
        add('Comparison/baseline', misHasAny(testsText.toLowerCase(), PR_COMPARE), 'Compare against a baseline, previous version or alternative');
        add('Measurement method', misWords(f('results')).length >= 18 || misHasAny(testsText.toLowerCase(), ['measured','benchmark','pilot','sample','latency','accuracy','precision','recall','f1']), 'State how the result was measured');
    } else if (key === 'security') {
        add('Concrete security controls', misCountHits(all, PR_SEC) >= 2, 'Hashing, auth, HTTPS, encryption, privacy, least privilege, etc.');
        add('Threat/data awareness', misHasAny(all, ['threat','attack','misuse','privacy','personal data','sensitive','risk','consent']), 'Identify what can go wrong');
        add('Limitation/mitigation', misWords(f('limitations')).length >= 8, 'Document an honest limitation and mitigation');
    } else if (key === 'ownership') {
        add('First-person ownership', misHasAny(f('role').toLowerCase(), PR_FIRST), 'Use “I built/designed/integrated…” where accurate');
        add('Specific modules', misWords(f('role')).length >= 12, `${misWords(f('role')).length} words describing your role`);
        add('Technical defense detail', misHasAny(f('role').toLowerCase(), PR_IMPL), 'Name implementation-level details you can defend');
    } else if (key === 'comm') {
        const wc = misWords(all).length;
        add('Substantive documentation', wc >= 120, `${wc} words across the submitted profile`);
        add('Demo/repository reference', !!f('link') || misHasAny(all, ['demo','deployed','hosted','github','repository']), 'Give reviewers a path to inspect the project');
        add('Setup/limitations clarity', misHasAny(all, ['install','setup','run','deploy','limitation','future']), 'Make reproduction and boundaries explicit');
    }
    const passed = checks.filter(x => x.ok).length;
    const ratio = checks.length ? passed / checks.length : 0;
    return { checks, passed, total: checks.length, ratio, status: prEvidenceStatus(Math.round(ratio * 100)) };
}
async function prReadZipBundle(file) {
    const buf = await file.arrayBuffer();
    const dv = new DataView(buf), bytes = new Uint8Array(buf), maxFiles = 80, maxTextPerFile = 90000, maxTotalText = 900000;
    let eocd = -1;
    for (let i = bytes.length - 22; i >= Math.max(0, bytes.length - 65557); i--) if (dv.getUint32(i, true) === 0x06054b50) { eocd = i; break; }
    if (eocd < 0) throw new Error('ZIP end record not found');
    const count = Math.min(dv.getUint16(eocd + 10, true), 6000), cdOffset = dv.getUint32(eocd + 16, true);
    const dec = new TextDecoder('utf-8', { fatal: false });
    const entries = []; let pos = cdOffset; let totalText = 0;
    for (let i = 0; i < count && pos + 46 <= bytes.length; i++) {
        if (dv.getUint32(pos, true) !== 0x02014b50) break;
        const method = dv.getUint16(pos + 10, true), csize = dv.getUint32(pos + 20, true), usize = dv.getUint32(pos + 24, true), nlen = dv.getUint16(pos + 28, true), xlen = dv.getUint16(pos + 30, true), clen = dv.getUint16(pos + 32, true), local = dv.getUint32(pos + 42, true);
        const name = dec.decode(bytes.slice(pos + 46, pos + 46 + nlen));
        entries.push({ name, method, csize, usize, local });
        pos += 46 + nlen + xlen + clen;
    }
    // Ignore dependency/build/VCS folders so a ZIP that includes node_modules still exposes the real source.
    const JUNK = /(^|\/)(node_modules|\.git|dist|build|__pycache__|\.venv|venv|\.next|\.cache|coverage)\//i;
    const kept = entries.filter(e => !JUNK.test(e.name));
    const textEntries = []; let readFiles = 0;
    for (const ent of kept) {
        if (totalText >= maxTotalText || readFiles >= 150 || ent.name.endsWith('/')) continue;
        const lower = ent.name.toLowerCase();
        const textLike = /\.(md|txt|json|csv|html?|css|js|jsx|ts|tsx|py|java|kt|c|cpp|h|sql|yaml|yml|toml|xml|env|sh|ps1|rs|go|rb|php)$/i.test(lower) || /(^|\/)(readme|license|dockerfile|package\.json|requirements\.txt|render\.yaml|vercel\.json)$/i.test(lower);
        if (!textLike || ent.csize > 500000 || ent.usize > 1200000) continue;
        const lp = ent.local;
        if (lp + 30 > bytes.length || dv.getUint32(lp, true) !== 0x04034b50) continue;
        const ln = dv.getUint16(lp + 26, true), lx = dv.getUint16(lp + 28, true), start = lp + 30 + ln + lx;
        let raw = bytes.slice(start, start + ent.csize);
        try {
            if (ent.method === 8) raw = new Uint8Array(await new Response(new Blob([raw]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer());
            else if (ent.method !== 0) continue;
            const text = dec.decode(raw).slice(0, maxTextPerFile);
            if (text.trim()) { textEntries.push({ name: ent.name, text }); totalText += text.length; readFiles++; }
        } catch (_) { /* unreadable compressed member: keep its filename in the manifest */ }
    }
    return { files: kept.map(e => e.name).slice(0, maxFiles), textEntries, fileCount: kept.length, size: file.size };
}
async function prReadProjectImport(file) {
    const lower = String(file && file.name || '').toLowerCase();
    if (!file || typeof file.arrayBuffer !== 'function') throw new Error('No readable project file was supplied.');
    if (lower.endsWith('.zip')) return Object.assign(await prReadZipBundle(file), { name: file.name });
    if (lower.endsWith('.pdf')) {
        await loadPdfJs(); const pdf = await window.pdfjsLib.getDocument({ data: await file.arrayBuffer(), disableWorker: true }).promise; let text = '';
        for (let i = 1; i <= Math.min(pdf.numPages, 40); i++) { const pg = await pdf.getPage(i); const c = await pg.getTextContent(); text += c.items.map(it => it.str).join(' ') + '\n'; }
        return { files: [file.name], textEntries: [{ name: file.name, text }], fileCount: 1, size: file.size };
    }
    return { files: [file.name], textEntries: [{ name: file.name, text: await file.text() }], fileCount: 1, size: file.size };
}
function prImportBundleToProfile(bundle, current) {
    const sourceName = String(bundle && bundle.name || 'Imported project');
    const texts = (bundle.textEntries || []).map(x => `\n--- ${x.name} ---\n${x.text}`).join('\n').slice(0, 140000);
    const readme = (bundle.textEntries || []).find(x => /(^|\/)readme(\.md|\.txt)?$/i.test(x.name)) || bundle.textEntries?.find(x => /readme/i.test(x.name));
    const pkg = (bundle.textEntries || []).find(x => /(^|\/)package\.json$/i.test(x.name));
    const fileManifest = (bundle.files || []).slice(0, 60).join('\n');
    const combined = [readme?.text || '', pkg?.text || '', texts].join('\n');
    const pick = (regex, fallback='') => { const m = combined.match(regex); return m ? String(m[1] || '').trim().slice(0, 6000) : fallback; };
    const stack = Array.from(new Set([...(current.stack || '').split(/[,\n/&+;|]+/).map(x => x.trim()).filter(Boolean), ...(combined.match(/\b(React|React Native|Node\.js|Express|PostgreSQL|Prisma|FastAPI|Python|Java|Spring Boot|MongoDB|MySQL|Docker|Kubernetes|TensorFlow|PyTorch|Tailwind|Next\.js|Vite|TypeScript|JavaScript)\b/gi) || [])])).slice(0, 18).join(', ');
    const title = current.title || sourceName.replace(/\.(zip|pdf|md|txt|markdown|json|csv)$/i, '').replace(/[_-]+/g, ' ') || 'Imported project';
    return Object.assign({}, current, {
        title, stack,
        abstract: current.abstract || pick(/(?:abstract|project overview|overview|description)\s*[:\-]\s*([\s\S]{80,1800}?)(?:\n\s*[A-Z][A-Za-z /&-]{2,40}:|$)/i, readme?.text?.slice(0, 1800) || ''),
        notes: `${(current.notes || '').trim()}\n\n[Imported project bundle: ${fileManifest ? bundle.fileCount + ' files' : '1 document'}]\n${texts}`.trim().slice(0, 30000),
        projectBundle: { name: sourceName, fileCount: bundle.fileCount, size: bundle.size, files: bundle.files, importedAt: new Date().toISOString(), readableFiles: (bundle.textEntries || []).map(x => x.name).slice(0, 40) }
    });
}

