    hist.forEach((e) => { if (e && Number.isFinite(Number(e.score))) ev.push({ kind: e.kind, score: misClamp(Number(e.score), 0, 100), date: e.date, ts: e.ts || Date.parse(e.date) || 0, raw: e }); });
