function p4Read(k, d) { try { const v = JSON.parse(localStorage.getItem(k)); return v == null ? d : v; } catch (_) { return d; } }
function p4Striver() {
  const st = p4Read('TNP_STRIVER_A2Z_V2', null);
  const items = st && typeof st === 'object' && st.items && typeof st.items === 'object' ? st.items : {};
  const log = st && st.log && typeof st.log === 'object' ? st.log : {};
  const today = striverDayKey();
  const keys = Object.keys(items);
  const done = keys.filter(k => items[k] && items[k].done);
  const due = done.filter(k => items[k].nextReview && items[k].nextReview <= today);
  let streak = 0; let d = today;
  if (!(log[d] > 0)) d = striverAddDays(d, -1);
  while (log[d] > 0) { streak += 1; d = striverAddDays(d, -1); }
  const week = [];
  for (let i = 6; i >= 0; i--) { const k = striverAddDays(today, -i); week.push({ k, n: Number(log[k]) || 0 }); }
  return { done: done.length, due: due.length, streak, week };
}
function p4Quiz() {
  const q = p4Read('TNP_QUIZ_HISTORY', []);
  const rows = (Array.isArray(q) ? q : []).filter(r => r && Number(r.total) > 0).map(r => Math.round(100 * Number(r.score) / Number(r.total)));
  const recent = rows.slice(0, 10).reverse();
  const avg = rows.length ? Math.round(rows.reduce((a, b) => a + b, 0) / rows.length) : null;
  const last3 = rows.slice(0, 3); const prev3 = rows.slice(3, 6);
  const mean = (x) => x.reduce((a, b) => a + b, 0) / x.length;
  const delta = last3.length && prev3.length ? Math.round(mean(last3) - mean(prev3)) : null;
  return { attempts: rows.length, avg, recent, latest: rows.length ? rows[0] : null, delta };
}

