(function () {
    const USER_KEY = 'CP_USER';

    function apiBase() {
        const url = (localStorage.getItem('AI_BACKEND_URL') || '').trim().replace(/\/+$/, '');
        return url; // '' -> same-origin, matching the existing /api/ai convention
    }

    async function rawFetch(path, opts) {
        const res = await fetch(`${apiBase()}${path}`, {
            credentials: 'include',
            ...opts,
            headers: { 'Content-Type': 'application/json', ...(opts && opts.headers) },
        });
        let data = null;
        try { data = await res.json(); } catch (_) { /* no body */ }
        if (!res.ok) {
            const raw = data && data.error;
            const msg = typeof raw === 'string' ? raw : (raw && typeof raw === 'object' ? String(raw.message || raw.code || `Request failed (${res.status})`) : (data && typeof data.message === 'string' ? data.message : `Request failed (${res.status})`));
            throw Object.assign(new Error(msg), { status: res.status, data });
        }
        return data;
    }

    async function authedFetch(path, opts) {
        try {
            return await rawFetch(path, { ...opts });
        } catch (err) {
            if (err.status === 401) {
                const refreshed = await tryRefresh();
                if (refreshed) {
                    return await rawFetch(path, { ...opts });
                }
                clearSession();
            }
            throw err;
        }
    }

    async function tryRefresh() {
        try {
            const data = await rawFetch('/api/auth/refresh', { method: 'POST' });
            localStorage.setItem(USER_KEY, JSON.stringify(data.user));
            localStorage.removeItem('CP_REFRESH_TOKEN');
            return true;
        } catch (_) { return false; }
    }

    function clearSession() {
        localStorage.removeItem('CP_ACCESS_TOKEN');
        localStorage.removeItem('CP_REFRESH_TOKEN');
        localStorage.removeItem(USER_KEY);
    }

    function storeSession(data) {
        localStorage.removeItem('CP_ACCESS_TOKEN');
        localStorage.removeItem('CP_REFRESH_TOKEN');
        localStorage.setItem(USER_KEY, JSON.stringify(data.user));
    }

    // Best-effort, silent-by-design: never throws, never interrupts whatever screen the
    // student is on. If they're not logged in, this simply does nothing.
    window.CP_syncResult = async function (type, topic, summaryScore, summaryLabel, payload) {
        if (!localStorage.getItem(USER_KEY)) return;
        try {
            await authedFetch('/api/results', {
                method: 'POST',
                body: JSON.stringify({ type, topic: topic || null, summaryScore, summaryLabel: summaryLabel || null, payload }),
            });
            window.dispatchEvent(new CustomEvent('cp-result-saved', { detail: { type } }));
        } catch (err) {
            console.warn('Could not sync result to account:', err.message);
        }
    };

    // Same best-effort/silent contract as CP_syncResult above. Persists a finished adaptive
    // diagnostic report (per-topic theta/p_know/mastery_status + the raw answer history) into
    // the Student Digital Twin (StudentCompetency + LearningEvent — see backend/src/routes/
    // twin.js) so it survives past the ai-ml-service in-memory session store, instead of only
    // living in the generic Result JSON blob that CP_syncResult writes. Idempotent server-side
    // on report.session_id, so calling this more than once for the same session is harmless.
    window.CP_syncTwinReport = async function (report) {
        if (!localStorage.getItem(USER_KEY)) return;
        if (!report || !Array.isArray(report.per_topic)) return;
        try {
            await authedFetch('/api/twin/sync-adaptive-report', {
                method: 'POST',
                body: JSON.stringify({ report }),
            });
            window.dispatchEvent(new CustomEvent('cp-twin-updated', { detail: { source: 'adaptive' } }));
        } catch (err) {
            console.warn('Could not sync diagnostic report to Digital Twin:', err.message);
        }
    };

    // Same best-effort/silent contract as CP_syncResult and CP_syncTwinReport above. Second
    // Digital Twin writer: turns a finished AI Mock Interviewer session's
    // Communication/Technical Depth/Problem Solving/Confidence rubric into real
    // StudentCompetency rows (see backend/src/routes/twin.js sync-interview-session) instead
    // of leaving interview performance stuck only in the generic Result JSON blob that
    // CP_syncResult writes. Idempotent server-side on sessionId.
    window.CP_syncTwinInterview = async function (sessionId, role, sessionSummary) {
        if (!localStorage.getItem(USER_KEY)) return;
        if (!sessionSummary || !sessionSummary.competency_rubric) return;
        try {
            await authedFetch('/api/twin/sync-interview-session', {
                method: 'POST',
                body: JSON.stringify({ sessionId, role: role || null, sessionSummary }),
            });
            window.dispatchEvent(new CustomEvent('cp-twin-updated', { detail: { source: 'interview' } }));
        } catch (err) {
            console.warn('Could not sync interview session to Digital Twin:', err.message);
        }
    };

    const h = React.createElement;
    const RESULT_LABELS = { QUIZ: 'Quizzes', INTERVIEW: 'Mock Interviews', ROADMAP: 'Roadmaps', RADAR: 'Skill Radar', RESUME_ANALYSIS: 'Resume Analyses', MIRROR_MENTOR: 'MirrorMentor Sessions' };

    function AccountWidget() {
        const [user, setUser] = React.useState(() => {
            try { return JSON.parse(localStorage.getItem(USER_KEY) || 'null'); } catch (_) { return null; }
        });
        const [open, setOpen] = React.useState(false);
        const [mode, setMode] = React.useState('login'); // 'login' | 'register' | 'panel'
        const [form, setForm] = React.useState({ email: '', password: '', name: '' });
        const [error, setError] = React.useState('');
        const [busy, setBusy] = React.useState(false);
        const [dashboard, setDashboard] = React.useState(null);

        React.useEffect(() => { setMode(user ? 'panel' : 'login'); }, [user]);

        const loadDashboard = React.useCallback(async () => {
            if (!user) return;
            try { setDashboard(await authedFetch('/api/results/dashboard')); }
            catch (_) { /* non-fatal — dashboard just stays empty */ }
        }, [user]);

        React.useEffect(() => {
            if (open && user) loadDashboard();
        }, [open, user, loadDashboard]);

        React.useEffect(() => {
            const onSaved = () => { if (open) loadDashboard(); };
            window.addEventListener('cp-result-saved', onSaved);
            return () => window.removeEventListener('cp-result-saved', onSaved);
        }, [open, loadDashboard]);

        const submit = async (e) => {
            e.preventDefault();
            setBusy(true); setError('');
            try {
                const path = mode === 'register' ? '/api/auth/register' : '/api/auth/login';
                const body = mode === 'register'
                    ? { email: form.email, password: form.password, name: form.name }
                    : { email: form.email, password: form.password };
                const data = await rawFetch(path, { method: 'POST', body: JSON.stringify(body) });
                storeSession(data);
                setUser(data.user);
                setForm({ email: '', password: '', name: '' });
            } catch (err) {
                setError(err.message || 'Something went wrong.');
            } finally { setBusy(false); }
        };

        const logout = async () => {
            clearSession();
            setUser(null);
            setDashboard(null);
            try { await rawFetch('/api/auth/logout', { method: 'POST' }); } catch (_) { /* already logged out locally */ }
        };

        const inputCls = "w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-400";

        return h(React.Fragment, null,
            h('button', {
                type: 'button', onClick: () => setOpen(true),
                className: 'fixed top-3 right-3 z-[60] flex items-center gap-1.5 bg-white/95 backdrop-blur border border-slate-200 shadow-md hover:shadow-lg rounded-full px-3 py-1.5 text-xs font-bold text-slate-700 transition',
                title: user ? `Signed in as ${user.name}` : 'Sign in to save your results',
            },
                h('span', { className: `w-2 h-2 rounded-full ${user ? 'bg-emerald-500' : 'bg-slate-300'}` }),
                user ? user.name.split(' ')[0] : 'Sign in'
            ),
            open && h('div', { className: 'fixed inset-0 z-[70] flex items-start justify-end p-3 sm:p-5', style: { background: 'rgba(15,23,42,0.35)' }, onClick: (e) => { if (e.target === e.currentTarget) setOpen(false); } },
                h('div', { className: 'w-full max-w-sm bg-white rounded-2xl shadow-2xl border border-slate-200 overflow-hidden' },
                    h('div', { className: 'flex items-center justify-between px-4 py-3 border-b border-slate-100' },
                        h('p', { className: 'text-sm font-black text-slate-800' }, user ? 'My Account' : mode === 'register' ? 'Create your account' : 'Sign in'),
                        h('button', { type: 'button', onClick: () => setOpen(false), className: 'text-slate-400 hover:text-slate-600 text-lg leading-none' }, '\u00d7')
                    ),
                    h('div', { className: 'p-4 space-y-3 max-h-[75vh] overflow-y-auto' },
                        !user && h('form', { onSubmit: submit, className: 'space-y-2.5' },
                            mode === 'register' && h('input', { className: inputCls, placeholder: 'Full name', value: form.name, onChange: (e) => setForm({ ...form, name: e.target.value }), required: true }),
                            h('input', { className: inputCls, type: 'email', placeholder: 'Email', value: form.email, onChange: (e) => setForm({ ...form, email: e.target.value }), required: true }),
                            h('input', { className: inputCls, type: 'password', placeholder: 'Password (min 8 characters)', value: form.password, onChange: (e) => setForm({ ...form, password: e.target.value }), minLength: 8, required: true }),
                            error && h('p', { className: 'text-[11px] text-rose-600 font-semibold' }, error),
                            h('button', { type: 'submit', disabled: busy, className: 'w-full py-2.5 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-60 text-white font-bold text-xs rounded-xl' },
                                busy ? 'Please wait\u2026' : mode === 'register' ? 'Create account' : 'Sign in'),
                            h('p', { className: 'text-[11px] text-slate-500 text-center' },
                                mode === 'register' ? 'Already have an account? ' : "Don't have an account? ",
                                h('button', { type: 'button', onClick: () => { setMode(mode === 'register' ? 'login' : 'register'); setError(''); }, className: 'text-indigo-600 font-bold underline' },
                                    mode === 'register' ? 'Sign in' : 'Create one')),
                            !apiBase() && h('p', { className: 'text-[10px] text-slate-400 bg-slate-50 border border-slate-200 rounded-lg px-2.5 py-2' },
                                'Using same-origin /api \u2014 if your backend is deployed separately, set Settings \u2192 AI Providers \u2192 Secure Backend URL first.')
                        ),
                        user && h('div', { className: 'space-y-3' },
                            h('div', { className: 'flex items-center gap-3' },
                                h('div', { className: 'w-10 h-10 rounded-full bg-indigo-600 text-white flex items-center justify-center font-black text-sm' }, user.name.charAt(0).toUpperCase()),
                                h('div', null,
                                    h('p', { className: 'text-sm font-bold text-slate-800' }, user.name),
                                    h('p', { className: 'text-[11px] text-slate-500' }, user.email))
                            ),
                            h('div', { className: 'border-t border-slate-100 pt-3' },
                                h('p', { className: 'text-[11px] font-black text-slate-500 uppercase tracking-wide mb-2' }, 'My Progress'),
                                !dashboard && h('p', { className: 'text-[11px] text-slate-400' }, 'Loading\u2026'),
                                dashboard && h('div', { className: 'space-y-1.5' },
                                    Object.entries(dashboard.byType || {}).filter(([, v]) => v.count > 0).map(([type, v]) =>
                                        h('div', { key: type, className: 'flex items-center justify-between bg-slate-50 border border-slate-200 rounded-lg px-3 py-2' },
                                            h('span', { className: 'text-xs font-semibold text-slate-700' }, RESULT_LABELS[type] || type),
                                            h('span', { className: 'text-xs text-slate-500' },
                                                `${v.count} saved` + (v.best !== null && v.best !== undefined ? ` \u00b7 best ${Math.round(v.best)}` : '')))
                                    ),
                                    dashboard.totalSessions === 0 && h('p', { className: 'text-[11px] text-slate-400' }, 'Finish a quiz, diagnostic, roadmap, or radar and it\u2019ll show up here automatically.')
                                )
                            ),
                            h('button', { type: 'button', onClick: logout, className: 'w-full py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs rounded-xl' }, 'Log out')
                        )
                    )
                )
            )
        );
    }

    // ===== Reusable Peer Benchmarking widget (exposed globally) =====
    // A small, drop-in component any tab can render once it has a numeric score:
    //   window.CPPeerBenchmark && React.createElement(window.CPPeerBenchmark, { type, topic, score })
    // Pulls an anonymized peer score list from the new backend (`/api/results/peer-stats`,
    // no names/IDs) and computes percentile/z-score/decile — via the AI/ML service's
    // `/benchmark/percentile` when Settings → AI/ML Intelligence Service URL is configured,
    // falling back to an identical calculation done locally in JS otherwise (same
    // graceful-degradation pattern the rest of the app already uses).
    function localPercentile(score, peers) {
        const scores = peers.filter((s) => s !== null && s !== undefined).sort((a, b) => a - b);
        const n = scores.length;
        if (n === 0) return { percentile: null, peer_count: 0, label: 'Not enough peer data yet \u2014 be the first to set the benchmark!' };
        const belowOrEqual = scores.filter((s) => s <= score).length;
        const percentile = Math.round((100 * belowOrEqual / n) * 10) / 10;
        const mean = scores.reduce((a, b) => a + b, 0) / n;
        let label = 'Below the median \u2014 room to close the gap.';
        if (percentile >= 90) label = 'Top 10% \u2014 exceptional performance among your peers.';
        else if (percentile >= 75) label = 'Top quartile \u2014 well above average.';
        else if (percentile >= 50) label = 'Above the median.';
        return { percentile, peer_count: n, mean: Math.round(mean * 10) / 10, label, your_score: score };
    }

    window.CPPeerBenchmark = function PeerBenchmark({ type, topic, score }) {
        const [stats, setStats] = React.useState(null);
        const [loading, setLoading] = React.useState(true);

        React.useEffect(() => {
            let cancelled = false;
            if (score === null || score === undefined) { setLoading(false); return; }
            setLoading(true);
            (async () => {
                try {
                    const qs = new URLSearchParams({ type, ...(topic ? { topic } : {}), excludeSelf: 'true' });
                    const peerRes = await fetch(`${apiBase()}/api/results/peer-stats?${qs.toString()}`, {
                        credentials: 'include',
                    }).then((r) => r.json());
                    const peerScores = (peerRes && peerRes.scores) || [];

                    const aimlBase = aimlBaseUrl();
                    let result = null;
                    if (aimlBase) {
                        try {
                            const res = await aimlFetch(`${aimlBase}/benchmark/percentile`, {
                                method: 'POST', headers: { 'Content-Type': 'application/json' },
                                body: JSON.stringify({ user_score: score, peer_scores: peerScores }),
                            });
                            if (res.ok) result = await res.json();
                        } catch (_) { /* falls through to local calc below */ }
                    }
                    if (!result) result = localPercentile(score, peerScores);
                    if (!cancelled) setStats(result);
                } catch (_) {
                    if (!cancelled) setStats(null);
                } finally {
                    if (!cancelled) setLoading(false);
                }
            })();
            return () => { cancelled = true; };
        }, [type, topic, score]);

        if (score === null || score === undefined) return null;
        if (loading) return h('p', { className: 'text-[11px] text-slate-400' }, 'Comparing to peers\u2026');
        if (!stats || stats.peer_count === 0) return h('p', { className: 'text-[11px] text-slate-400' }, stats ? stats.label : 'Peer comparison unavailable right now.');

        return h('div', { className: 'bg-violet-50 border border-violet-100 rounded-xl p-3 space-y-1' },
            h('p', { className: 'text-[10px] font-black text-violet-700 uppercase' }, 'Peer Benchmarking'),
            h('p', { className: 'text-xs text-violet-800' },
                stats.percentile !== null ? `You're ahead of ${stats.percentile}% of ${stats.peer_count} peers.` : `${stats.peer_count} peer results so far.`),
            h('p', { className: 'text-[11px] text-violet-600' }, stats.label)
        );
    };

    const mountEl = document.createElement('div');
    mountEl.id = 'cp-account-widget-root';
    document.body.appendChild(mountEl);
    ReactDOM.createRoot(mountEl).render(h(AccountWidget));
})();

